#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\AuditPage")]
#[serde(default)]
pub struct AuditPage {
    /// The entries on this page, in chain order.
    pub entries: Vec<AuditEntry>,
    /// Where the caller resumes: the position of the **last** entry on this page, or
    /// `None` when the page is empty.
    ///
    /// # Why `None` means "this page was empty", not "the history is finished"
    ///
    /// An append-only chain is never finished — it is only momentarily caught up. Had
    /// `next` gone `None` as soon as a page ran short of `limit`, a caller that had
    /// reached the end would be left holding no resumable position at all, and its only
    /// way back would be to re-read from the beginning and de-duplicate. So the rule is:
    /// a non-empty page always yields a cursor, and a caller that wants the whole history
    /// pages until it gets an empty one. A caller that wants to keep following the chain
    /// simply keeps the last cursor it was given and asks again later.
    pub next: Option<AuditCursor>,
}

#[php_impl]
impl AuditPage {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(entries: &ext_php_rs::types::ZendHashTable, next: Option<&AuditCursor>) -> PhpResult<Self> {
        let mut entries_core_result: Vec<AuditEntry> = Vec::new();
        for (_, item) in entries.iter() {
            if let Some(parsed) = <&AuditEntry as ext_php_rs::convert::FromZval>::from_zval(item) {
                entries_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to AuditEntry".to_string(),
                ));
            }
        }
        let entries_core: Vec<AuditEntry> = entries_core_result;
        Ok(Self {
            entries: entries_core,
            next: next.cloned(),
        })
    }

    #[php(getter)]
    pub fn get_entries(&self) -> Vec<AuditEntry> {
        self.entries.clone()
    }
    #[php(name = "getEntries")]
    pub fn read_entries(&self) -> Vec<AuditEntry> {
        self.get_entries()
    }

    #[php(getter)]
    pub fn get_next(&self) -> Option<AuditCursor> {
        self.next.clone().map(Into::into)
    }
    #[php(name = "getNext")]
    pub fn read_next(&self) -> Option<AuditCursor> {
        self.get_next()
    }

    pub fn set_next(&mut self, value: Option<&AuditCursor>) {
        self.next = value.map(|value| value.clone().into());
    }
}

