#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\ChunkClassificationConfig")]
#[serde(default)]
pub struct ChunkClassificationConfig {
    /// Minijinja prompt template. Receives `{{ definitions }}` (rendered label +
    /// description list) and `{{ chunks }}` (a numbered list of chunk texts in
    /// the current batch) variables. `None` lets the backend pick a sensible
    /// default.
    #[php(prop, name = "promptTemplate")]
    #[serde(alias = "promptTemplate")]
    pub prompt_template: Option<String>,
    /// The set of label definitions the classifier may emit. Must contain at
    /// least one entry.
    pub definitions: Vec<ChunkClassificationDefinition>,
    /// LLM configuration used for classification.
    pub llm: LlmConfig,
    /// Number of chunks batched into a single LLM request.
    ///
    /// Larger batches amortize the fixed prompt cost (definitions block) across
    /// more chunks, at the risk of exceeding the model's context window for
    /// very large taxonomies or chunk texts. Defaults to `DEFAULT_BATCH_SIZE`.
    #[php(prop, name = "batchSize")]
    #[serde(alias = "batchSize")]
    pub batch_size: i64,
    /// Maximum number of in-flight batch requests.
    ///
    /// Bounds concurrency against the configured LLM provider. Defaults to
    /// `DEFAULT_MAX_CONCURRENCY`.
    #[php(prop, name = "maxConcurrency")]
    #[serde(alias = "maxConcurrency")]
    pub max_concurrency: i64,
}

#[php_impl]
impl ChunkClassificationConfig {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        definitions: &ext_php_rs::types::ZendHashTable,
        llm: &LlmConfig,
        batchSize: i64,
        maxConcurrency: i64,
        promptTemplate: Option<String>,
    ) -> PhpResult<Self> {
        let mut definitions_core_result: Vec<ChunkClassificationDefinition> = Vec::new();
        for (_, item) in definitions.iter() {
            if let Some(parsed) = <&ChunkClassificationDefinition as ext_php_rs::convert::FromZval>::from_zval(item) {
                definitions_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to ChunkClassificationDefinition".to_string(),
                ));
            }
        }
        let definitions_core: Vec<ChunkClassificationDefinition> = definitions_core_result;
        Ok(Self {
            prompt_template: promptTemplate,
            definitions: definitions_core,
            llm: llm.clone(),
            batch_size: batchSize,
            max_concurrency: maxConcurrency,
        })
    }

    pub fn get_prompt_template(&self) -> Option<String> {
        self.prompt_template.clone()
    }

    #[php(getter)]
    pub fn get_definitions(&self) -> Vec<ChunkClassificationDefinition> {
        self.definitions.clone()
    }
    #[php(name = "getDefinitions")]
    pub fn read_definitions(&self) -> Vec<ChunkClassificationDefinition> {
        self.get_definitions()
    }

    #[php(getter)]
    pub fn get_llm(&self) -> LlmConfig {
        self.llm.clone()
    }
    #[php(name = "getLlm")]
    pub fn read_llm(&self) -> LlmConfig {
        self.get_llm()
    }

    pub fn get_batch_size(&self) -> i64 {
        self.batch_size.clone()
    }

    pub fn get_max_concurrency(&self) -> i64 {
        self.max_concurrency.clone()
    }
}

