#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\EditorProjectionOptions")]
#[serde(default)]
pub struct EditorProjectionOptions {
    /// Stable document reference. The projection does not interpret this value.
    #[php(prop, name = "documentRef")]
    #[serde(alias = "documentRef")]
    pub document_ref: String,
    /// Stable version reference. The projection does not interpret this value.
    #[php(prop, name = "versionRef")]
    #[serde(alias = "versionRef")]
    pub version_ref: String,
    /// Source label used in token provenance (normally `hacienda`).
    #[php(prop, name = "source")]
    pub source: String,
    /// Redaction mode used for this document, if known.
    #[php(prop, name = "redactionMode")]
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(alias = "redactionMode")]
    #[serde(default)]
    pub redaction_mode: Option<String>,
    /// Source-text provenance supplied by the redaction pipeline.
    ///
    /// `start` and `end` refer to the pre-redaction source only. They are never used to
    /// locate or decorate a character in the editor document.
    #[serde(default)]
    pub redactions: Vec<SourceRedactionProvenance>,
}

#[php_impl]
impl EditorProjectionOptions {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        documentRef: String,
        versionRef: String,
        source: String,
        redactions: &ext_php_rs::types::ZendHashTable,
        redactionMode: Option<String>,
    ) -> PhpResult<Self> {
        let mut redactions_core_result: Vec<SourceRedactionProvenance> = Vec::new();
        for (_, item) in redactions.iter() {
            if let Some(parsed) = <&SourceRedactionProvenance as ext_php_rs::convert::FromZval>::from_zval(item) {
                redactions_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to SourceRedactionProvenance".to_string(),
                ));
            }
        }
        let redactions_core: Vec<SourceRedactionProvenance> = redactions_core_result;
        Ok(Self {
            document_ref: documentRef,
            version_ref: versionRef,
            source,
            redaction_mode: redactionMode,
            redactions: redactions_core,
        })
    }

    pub fn get_document_ref(&self) -> String {
        self.document_ref.clone()
    }

    pub fn get_version_ref(&self) -> String {
        self.version_ref.clone()
    }

    pub fn get_source(&self) -> String {
        self.source.clone()
    }

    pub fn get_redaction_mode(&self) -> Option<String> {
        self.redaction_mode.clone().map(Into::into)
    }

    #[php(getter)]
    pub fn get_redactions(&self) -> Vec<SourceRedactionProvenance> {
        self.redactions.clone()
    }
    #[php(name = "getRedactions")]
    pub fn read_redactions(&self) -> Vec<SourceRedactionProvenance> {
        self.get_redactions()
    }

    pub fn with_source(&self, source: String) -> EditorProjectionOptions {
        let core_self = hacienda::editor_projection::EditorProjectionOptions {
                document_ref: self.document_ref.clone(),
                version_ref: self.version_ref.clone(),
                source: self.source.clone(),
                redaction_mode: self.redaction_mode.as_deref().map(|s| match s { "mask" => hacienda::redaction::RedactionMode::Mask,"hash" => hacienda::redaction::RedactionMode::Hash,"pseudonymize" => hacienda::redaction::RedactionMode::Pseudonymize,"remove" => hacienda::redaction::RedactionMode::Remove,"custom" => hacienda::redaction::RedactionMode::Custom,other => {
        ext_php_rs::exception::PhpException::from_message(format!(
            "invalid value {other:?} for field 'redaction_mode' of RedactionMode: expected one of [mask, hash, pseudonymize, remove, custom]"
        ))
        .throw();
        Default::default()
    }
     })
    ,
                redactions: self.redactions.clone().into_iter().map(Into::into).collect(),
            };
        core_self.with_source(source).into()
    }
}

