#[derive(Clone)]
#[php_class]
#[php(name = "Hacienda\\EntityGlossary")]
pub struct EntityGlossary {
    inner: Arc<std::sync::Mutex<hacienda::glossary::EntityGlossary>>,
}

#[php_impl]
impl EntityGlossary {
    /// Record every entity detected in `text`.
    ///
    /// The mention is read back out of `text` by byte offset rather than taken from
    /// `MergedEntity::text`, which is empty for regex detections — those carry
    /// offsets only.
    pub fn observe(&self, text: String, entities: &ext_php_rs::types::ZendHashTable) {
        let mut entities_core_result: Vec<hacienda::MergedEntity> = Vec::new();
        for (_, item) in entities.iter() {
            if let Some(parsed) = <&MergedEntity as ext_php_rs::convert::FromZval>::from_zval(item) {
                entities_core_result.push(parsed.clone().into());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to MergedEntity".to_string(),
                ));
            }
        }
        let entities_core: Vec<hacienda::MergedEntity> = entities_core_result;
        self.inner.lock().unwrap().observe(&text, &entities_core[..])
    }

    /// Terms that meet `GlossaryConfig::min_count`, most frequent first.
    pub fn entries(&self) -> Vec<GlossaryEntry> {
        self.inner
            .lock()
            .unwrap()
            .entries()
            .into_iter()
            .map(Into::into)
            .collect()
    }

    pub fn is_empty(&self) -> bool {
        self.inner.lock().unwrap().is_empty()
    }

    /// Rewrite every published term in `text` as a link to its glossary entry.
    ///
    /// Matches are resolved in one pass over non-overlapping ranges, so a term that
    /// contains another term never produces a nested link.
    pub fn link(&self, text: String) -> String {
        self.inner.lock().unwrap().link(&text)
    }

    /// Render the glossary itself as a markdown section.
    pub fn to_markdown(&self) -> String {
        self.inner.lock().unwrap().to_markdown()
    }
}

