impl Default for ExtractedImage {
    fn default() -> Self {
        <xberg::ExtractedImage as Default>::default().into()
    }
}

#[php_impl]
impl ExtractedImage {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        data: PhpBytes,
        format: String,
        imageIndex: u32,
        isMask: bool,
        pageNumber: Option<u32>,
        width: Option<u32>,
        height: Option<u32>,
        colorspace: Option<String>,
        bitsPerComponent: Option<u32>,
        description: Option<String>,
        ocrResult: Option<&ExtractedDocument>,
        boundingBox: Option<&BoundingBox>,
        sourcePath: Option<String>,
        imageKind: Option<String>,
        kindConfidence: Option<f32>,
        clusterId: Option<u32>,
        caption: Option<String>,
        qrCodes: Option<&ext_php_rs::types::ZendHashTable>,
        dataBase64: Option<String>,
    ) -> PhpResult<Self> {
        let qrCodes_core: Option<Vec<QrCode>> = if let Some(ht) = qrCodes {
            let mut result = Vec::new();
            for (_, item) in ht.iter() {
                if let Some(parsed) = <&QrCode as ext_php_rs::convert::FromZval>::from_zval(item) {
                    result.push(parsed.clone());
                } else {
                    return Err(ext_php_rs::exception::PhpException::from_message(
                        "Failed to convert array element to QrCode".to_string(),
                    ));
                }
            }
            Some(result)
        } else {
            None
        };
        Ok(Self {
            data: data.0,
            format,
            image_index: imageIndex,
            page_number: pageNumber,
            width,
            height,
            colorspace,
            bits_per_component: bitsPerComponent,
            is_mask: isMask,
            description,
            ocr_result: ocrResult.cloned(),
            bounding_box: boundingBox.cloned(),
            source_path: sourcePath,
            image_kind: imageKind,
            kind_confidence: kindConfidence,
            cluster_id: clusterId,
            caption,
            qr_codes: qrCodes_core,
            data_base64: dataBase64,
        })
    }

    #[php(getter)]
    pub fn get_data(&self) -> Vec<u8> {
        self.data.clone()
    }
    #[php(name = "getData")]
    pub fn read_data(&self) -> Vec<u8> {
        self.get_data()
    }

    pub fn get_format(&self) -> String {
        self.format.clone()
    }

    pub fn get_image_index(&self) -> u32 {
        self.image_index.clone()
    }

    pub fn get_page_number(&self) -> Option<u32> {
        self.page_number.clone()
    }

    pub fn get_width(&self) -> Option<u32> {
        self.width.clone()
    }

    pub fn get_height(&self) -> Option<u32> {
        self.height.clone()
    }

    pub fn get_colorspace(&self) -> Option<String> {
        self.colorspace.clone()
    }

    pub fn get_bits_per_component(&self) -> Option<u32> {
        self.bits_per_component.clone()
    }

    pub fn get_is_mask(&self) -> bool {
        self.is_mask.clone()
    }

    pub fn get_description(&self) -> Option<String> {
        self.description.clone()
    }

    #[php(getter)]
    pub fn get_ocr_result(&self) -> Option<ExtractedDocument> {
        self.ocr_result.clone().map(Into::into)
    }
    #[php(name = "getOcrResult")]
    pub fn read_ocr_result(&self) -> Option<ExtractedDocument> {
        self.get_ocr_result()
    }

    pub fn set_ocr_result(&mut self, value: Option<&ExtractedDocument>) {
        self.ocr_result = value.map(|value| value.clone().into());
    }

    #[php(getter)]
    pub fn get_bounding_box(&self) -> Option<BoundingBox> {
        self.bounding_box.clone().map(Into::into)
    }
    #[php(name = "getBoundingBox")]
    pub fn read_bounding_box(&self) -> Option<BoundingBox> {
        self.get_bounding_box()
    }

    pub fn set_bounding_box(&mut self, value: Option<&BoundingBox>) {
        self.bounding_box = value.map(|value| value.clone().into());
    }

    pub fn get_source_path(&self) -> Option<String> {
        self.source_path.clone()
    }

    pub fn get_image_kind(&self) -> Option<String> {
        self.image_kind.clone().map(Into::into)
    }

    pub fn get_kind_confidence(&self) -> Option<f32> {
        self.kind_confidence.clone()
    }

    pub fn get_cluster_id(&self) -> Option<u32> {
        self.cluster_id.clone()
    }

    pub fn get_caption(&self) -> Option<String> {
        self.caption.clone()
    }

    #[php(getter)]
    pub fn get_qr_codes(&self) -> Option<Vec<QrCode>> {
        self.qr_codes.clone()
    }
    #[php(name = "getQrCodes")]
    pub fn read_qr_codes(&self) -> Option<Vec<QrCode>> {
        self.get_qr_codes()
    }

    pub fn get_data_base64(&self) -> Option<String> {
        self.data_base64.clone()
    }
}

