#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "Hacienda\\ExtractionResult")]
#[serde(default)]
pub struct ExtractionResult {
    /// Extracted documents in discovery order.
    pub results: Vec<ExtractedDocument>,
    /// Non-fatal per-input errors.
    #[serde(default)]
    pub errors: Vec<ExtractionErrorItem>,
    /// Aggregate counts for the operation.
    pub summary: ExtractionSummary,
    /// Final URLs reached after redirects during URL ingestion.
    #[php(prop, name = "crawlFinalUrls")]
    #[serde(alias = "crawlFinalUrls")]
    #[serde(default)]
    pub crawl_final_urls: Vec<String>,
    /// Total redirects followed while fetching or crawling URLs.
    #[php(prop, name = "crawlRedirectCount")]
    #[serde(alias = "crawlRedirectCount")]
    #[serde(default)]
    pub crawl_redirect_count: i64,
    /// Unique normalized URLs discovered by crawls.
    #[php(prop, name = "crawlUniqueNormalizedUrls")]
    #[serde(alias = "crawlUniqueNormalizedUrls")]
    #[serde(default)]
    pub crawl_unique_normalized_urls: Vec<String>,
}

impl Default for ExtractionResult {
    fn default() -> Self {
        <xberg::ExtractionResult as Default>::default().into()
    }
}

#[php_impl]
impl ExtractionResult {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        results: &ext_php_rs::types::ZendHashTable,
        errors: &ext_php_rs::types::ZendHashTable,
        summary: &ExtractionSummary,
        crawlFinalUrls: Vec<String>,
        crawlRedirectCount: i64,
        crawlUniqueNormalizedUrls: Vec<String>,
    ) -> PhpResult<Self> {
        let mut results_core_result: Vec<ExtractedDocument> = Vec::new();
        for (_, item) in results.iter() {
            if let Some(parsed) = <&ExtractedDocument as ext_php_rs::convert::FromZval>::from_zval(item) {
                results_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to ExtractedDocument".to_string(),
                ));
            }
        }
        let results_core: Vec<ExtractedDocument> = results_core_result;
        let mut errors_core_result: Vec<ExtractionErrorItem> = Vec::new();
        for (_, item) in errors.iter() {
            if let Some(parsed) = <&ExtractionErrorItem as ext_php_rs::convert::FromZval>::from_zval(item) {
                errors_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to ExtractionErrorItem".to_string(),
                ));
            }
        }
        let errors_core: Vec<ExtractionErrorItem> = errors_core_result;
        Ok(Self {
            results: results_core,
            errors: errors_core,
            summary: summary.clone(),
            crawl_final_urls: crawlFinalUrls,
            crawl_redirect_count: crawlRedirectCount,
            crawl_unique_normalized_urls: crawlUniqueNormalizedUrls,
        })
    }

    #[php(getter)]
    pub fn get_results(&self) -> Vec<ExtractedDocument> {
        self.results.clone()
    }
    #[php(name = "getResults")]
    pub fn read_results(&self) -> Vec<ExtractedDocument> {
        self.get_results()
    }

    #[php(getter)]
    pub fn get_errors(&self) -> Vec<ExtractionErrorItem> {
        self.errors.clone()
    }
    #[php(name = "getErrors")]
    pub fn read_errors(&self) -> Vec<ExtractionErrorItem> {
        self.get_errors()
    }

    #[php(getter)]
    pub fn get_summary(&self) -> ExtractionSummary {
        self.summary.clone()
    }
    #[php(name = "getSummary")]
    pub fn read_summary(&self) -> ExtractionSummary {
        self.get_summary()
    }

    pub fn get_crawl_final_urls(&self) -> Vec<String> {
        self.crawl_final_urls.clone()
    }

    pub fn get_crawl_redirect_count(&self) -> i64 {
        self.crawl_redirect_count.clone()
    }

    pub fn get_crawl_unique_normalized_urls(&self) -> Vec<String> {
        self.crawl_unique_normalized_urls.clone()
    }
}

