#[derive(Clone)]
#[php_class]
#[php(name = "Hacienda\\FileReviewStore")]
pub struct FileReviewStore {
    inner: Arc<hacienda::review::FileReviewStore>,
}

#[php_impl]
impl FileReviewStore {
    pub fn submit(&self, tenant: &TenantId, item: &ReviewQueueItem) -> PhpResult<ReviewQueueItem> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner
                .submit(&tenant.inner, item.clone().into())
                .await
                .map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    pub fn assign(&self, tenant: &TenantId, id: String, reviewer: String) -> PhpResult<ReviewQueueItem> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner
                .assign(&tenant.inner, &id, &reviewer)
                .await
                .map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    pub fn decide(
        &self,
        tenant: &TenantId,
        id: String,
        decision: String,
        reviewer: String,
        comment: String,
    ) -> PhpResult<ReviewQueueItem> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner
                .decide(
                    &tenant.inner,
                    &id,
                    serde_json::from_str(&serde_json::to_string(&decision).unwrap_or_default()).unwrap_or_default(),
                    &reviewer,
                    &comment,
                )
                .await
                .map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    pub fn list(&self, tenant: &TenantId, filter: Option<String>) -> PhpResult<Vec<ReviewQueueItem>> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner
                .list(
                    &tenant.inner,
                    filter
                        .as_deref()
                        .and_then(|s| serde_json::from_str(&serde_json::to_string(s).unwrap_or_default()).ok()),
                )
                .await
                .map_err(alef_php_err)?;
            Ok(result.into_iter().map(Into::into).collect())
        })
    }

    pub fn get(&self, tenant: &TenantId, id: String) -> PhpResult<Option<ReviewQueueItem>> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.get(&tenant.inner, &id).await.map_err(alef_php_err)?;
            Ok(result.map(Into::into))
        })
    }

    pub fn stats(&self, tenant: &TenantId) -> PhpResult<QueueStats> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.stats(&tenant.inner).await.map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    /// Open (or create) a durable review store at `path`.
    ///
    /// If the file already exists its events are replayed to reconstruct state. An
    /// unterminated trailing record is *removed from the file* with a warning; a
    /// malformed line that is properly terminated is a hard error.
    ///
    /// Removing rather than merely skipping the partial record is what makes the log
    /// writable again. `append` writes at EOF, so a fragment left in place would be
    /// welded to the next event on the same physical line — and that welded line, being
    /// last, would itself look truncated. Every subsequent write would be accepted,
    /// fsynced, and silently discarded. Truncation happens once, here, under the
    /// caller's control.
    ///
    /// # Errors
    ///
    /// - `ReviewError::Io` — file creation, read, or truncation failed.
    /// - `ReviewError::Json` — a terminated line is not valid JSON.
    #[php(name = "open")]
    pub fn open(path: String) -> PhpResult<FileReviewStore> {
        hacienda::review::FileReviewStore::open(std::path::PathBuf::from(path))
            .map(|val| Self { inner: Arc::new(val) })
            .map_err(alef_php_err)
    }
}

#[derive(Clone)]
#[php_class]
#[php(name = "Hacienda\\FileSink")]
pub struct FileSink {
    inner: Arc<std::sync::Mutex<hacienda::audit::FileSink>>,
}

#[php_impl]
impl FileSink {
    pub fn chain(&self) -> AuditChain {
        AuditChain {
            inner: Arc::new(std::sync::Mutex::new(self.inner.lock().unwrap().chain().clone())),
        }
    }

    pub fn chain_mut(&self) -> AuditChain {
        AuditChain {
            inner: Arc::new(std::sync::Mutex::new(self.inner.lock().unwrap().chain_mut().clone())),
        }
    }

    pub fn write(&self, entry: &AuditEntry) -> PhpResult<()> {
        let entry_core: hacienda::AuditEntry = entry.clone().into();
        self.inner.lock().unwrap().write(&entry_core).map_err(alef_php_err)?;
        Ok(())
    }

    pub fn flush(&self) -> PhpResult<()> {
        self.inner.lock().unwrap().flush().map_err(alef_php_err)?;
        Ok(())
    }

    pub fn rotate(&self) -> PhpResult<()> {
        self.inner.lock().unwrap().rotate().map_err(alef_php_err)?;
        Ok(())
    }

    /// Open (or create) the log at `path` and resume its chain under `config_hash`.
    ///
    /// # Errors
    ///
    /// Returns `AuditError::Io` if the file cannot be opened or its size read.
    #[php(name = "new")]
    pub fn new(path: String, maxSize: i64, maxFiles: u32, configHash: String) -> PhpResult<FileSink> {
        hacienda::audit::FileSink::new(std::path::PathBuf::from(path), maxSize as u64, maxFiles, configHash)
            .map(|val| Self {
                inner: Arc::new(std::sync::Mutex::new(val)),
            })
            .map_err(alef_php_err)
    }
}

#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\Footnote")]
#[serde(default)]
pub struct Footnote {
    /// Footnote label
    #[php(prop, name = "label")]
    pub label: String,
    /// Footnote content blocks
    pub content: Vec<FormattedBlock>,
}

#[php_impl]
impl Footnote {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(label: String, content: &ext_php_rs::types::ZendHashTable) -> PhpResult<Self> {
        let mut content_core_result: Vec<FormattedBlock> = Vec::new();
        for (_, item) in content.iter() {
            if let Some(parsed) = <&FormattedBlock as ext_php_rs::convert::FromZval>::from_zval(item) {
                content_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to FormattedBlock".to_string(),
                ));
            }
        }
        let content_core: Vec<FormattedBlock> = content_core_result;
        Ok(Self {
            label,
            content: content_core,
        })
    }

    pub fn get_label(&self) -> String {
        self.label.clone()
    }

    #[php(getter)]
    pub fn get_content(&self) -> Vec<FormattedBlock> {
        self.content.clone()
    }
    #[php(name = "getContent")]
    pub fn read_content(&self) -> Vec<FormattedBlock> {
        self.get_content()
    }
}

#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\FormattedBlock")]
#[serde(default)]
pub struct FormattedBlock {
    /// Type of block element
    #[php(prop, name = "blockType")]
    #[serde(skip_serializing_if = "String::is_empty")]
    #[serde(alias = "blockType")]
    pub block_type: String,
    /// Heading level (1-6) for headings, or nesting level for lists
    #[php(prop, name = "level")]
    pub level: Option<i64>,
    /// Inline content within the block
    #[serde(alias = "inlineContent")]
    pub inline_content: Vec<InlineElement>,
    /// Element attributes (classes, IDs, key-value pairs)
    pub attributes: Option<Attributes>,
    /// Language identifier for code blocks
    #[php(prop, name = "language")]
    pub language: Option<String>,
    /// Raw code content for code blocks
    #[php(prop, name = "code")]
    pub code: Option<String>,
    /// Nested blocks for containers (blockquotes, list items, divs)
    #[serde(default)]
    pub children: Vec<FormattedBlock>,
}

#[php_impl]
impl FormattedBlock {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        blockType: String,
        inlineContent: &ext_php_rs::types::ZendHashTable,
        children: &ext_php_rs::types::ZendHashTable,
        level: Option<i64>,
        attributes: Option<&Attributes>,
        language: Option<String>,
        code: Option<String>,
    ) -> PhpResult<Self> {
        let mut inlineContent_core_result: Vec<InlineElement> = Vec::new();
        for (_, item) in inlineContent.iter() {
            if let Some(parsed) = <&InlineElement as ext_php_rs::convert::FromZval>::from_zval(item) {
                inlineContent_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to InlineElement".to_string(),
                ));
            }
        }
        let inlineContent_core: Vec<InlineElement> = inlineContent_core_result;
        let mut children_core_result: Vec<FormattedBlock> = Vec::new();
        for (_, item) in children.iter() {
            if let Some(parsed) = <&FormattedBlock as ext_php_rs::convert::FromZval>::from_zval(item) {
                children_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to FormattedBlock".to_string(),
                ));
            }
        }
        let children_core: Vec<FormattedBlock> = children_core_result;
        Ok(Self {
            block_type: blockType,
            level,
            inline_content: inlineContent_core,
            attributes: attributes.cloned(),
            language,
            code,
            children: children_core,
        })
    }

    pub fn get_block_type(&self) -> String {
        self.block_type.clone()
    }

    pub fn get_level(&self) -> Option<i64> {
        self.level.clone()
    }

    #[php(getter)]
    pub fn get_inline_content(&self) -> Vec<InlineElement> {
        self.inline_content.clone()
    }
    #[php(name = "getInlineContent")]
    pub fn read_inline_content(&self) -> Vec<InlineElement> {
        self.get_inline_content()
    }

    #[php(getter)]
    pub fn get_attributes(&self) -> Option<Attributes> {
        self.attributes.clone().map(Into::into)
    }
    #[php(name = "getAttributes")]
    pub fn read_attributes(&self) -> Option<Attributes> {
        self.get_attributes()
    }

    pub fn set_attributes(&mut self, value: Option<&Attributes>) {
        self.attributes = value.map(|value| value.clone().into());
    }

    pub fn get_language(&self) -> Option<String> {
        self.language.clone()
    }

    pub fn get_code(&self) -> Option<String> {
        self.code.clone()
    }

    #[php(getter)]
    pub fn get_children(&self) -> Vec<FormattedBlock> {
        self.children.clone()
    }
    #[php(name = "getChildren")]
    pub fn read_children(&self) -> Vec<FormattedBlock> {
        self.get_children()
    }
}

#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\Formula")]
#[serde(default)]
pub struct Formula {
    /// LaTeX source of the formula, without surrounding `$$` delimiters.
    ///
    /// Markup converters and formula OCR produce real LaTeX. The native PDF
    /// layout path stores the plain text of a detected formula region, which
    /// keeps the original Unicode math characters instead of LaTeX commands.
    /// To render the formula in Markdown or other formats, wrap it in `$$..$$`.
    #[php(prop, name = "latex")]
    pub latex: String,
    /// Bounding box of the formula region on its page. `None` for markup sources.
    ///
    /// PDF OCR sources report PDF point coordinates with the origin at the
    /// bottom-left of the page, comparable to native PDF geometry. Image
    /// sources, and PDF pages whose geometry is unavailable, report pixels of
    /// the image the OCR backend saw. The C FFI reports an absent bbox as a
    /// null pointer.
    #[serde(default)]
    pub bbox: Option<BoundingBox>,
    /// 1-indexed page number the formula appears on. `None` when the source
    /// format has no page concept. The C FFI reports an absent page as `0`.
    #[php(prop, name = "page")]
    #[serde(default)]
    pub page: Option<u32>,
}

#[php_impl]
impl Formula {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(latex: String, bbox: Option<&BoundingBox>, page: Option<u32>) -> Self {
        Self {
            latex,
            bbox: bbox.cloned(),
            page,
        }
    }

    pub fn get_latex(&self) -> String {
        self.latex.clone()
    }

    #[php(getter)]
    pub fn get_bbox(&self) -> Option<BoundingBox> {
        self.bbox.clone().map(Into::into)
    }
    #[php(name = "getBbox")]
    pub fn read_bbox(&self) -> Option<BoundingBox> {
        self.get_bbox()
    }

    pub fn set_bbox(&mut self, value: Option<&BoundingBox>) {
        self.bbox = value.map(|value| value.clone().into());
    }

    pub fn get_page(&self) -> Option<u32> {
        self.page.clone()
    }
}

