#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "Hacienda\\HaciendaConfig")]
#[serde(default)]
pub struct HaciendaConfig {
    pub extraction: ExtractionConfig,
    /// Which installation this process belongs to: `LocalFull` or `TeamOnPremise`.
    ///
    /// This is the first-class `[installation]` section of issue #142. It is the *same*
    /// type the desktop client reads from `HACIENDA_INSTALLATION_CONFIG`, resolved by
    /// `hacienda_installation.resolve_installation` and validated by
    /// `InstallationConfig.validate_for`, so client and server cannot grow two ideas
    /// of what an installation means (dossier `docs/wayfinder/131-installations.md` §I1,
    /// gap É1).
    ///
    /// `None` means no source declared one. That is correct for the one-shot commands —
    /// `hacienda extract` runs inside its own process boundary and needs no topology —
    /// but `hacienda serve` refuses to start without it: a network-facing process has to
    /// say which installation it is rather than be assumed to be one.
    #[php(prop, name = "installation")]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub installation: Option<String>,
    /// Detection and redaction. `None` extracts without touching PII.
    pub pii: Option<PipelineConfig>,
    pub compliance: Option<ComplianceConfig>,
    /// Human review queue for low-confidence detections.
    ///
    /// Requires `pii`: there is nothing to review without detections.
    pub review: Option<ReviewConfig>,
    pub glossary: Option<GlossaryConfig>,
    /// Authentication for `hacienda serve`. Disabled by default, which is correct for
    /// the CLI and the desktop app: there, the process boundary *is* the trust boundary.
    ///
    /// It is not a field the CLI reads — `hacienda extract` is always `Caller.Trusted`.
    /// It lives here so that one config file describes the whole product, and so that
    /// `hacienda serve` can refuse a non-loopback bind when it is off.
    pub auth: AuthConfig,
}

impl Default for HaciendaConfig {
    fn default() -> Self {
        <hacienda::HaciendaConfig as Default>::default().into()
    }
}

#[php_impl]
impl HaciendaConfig {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        extraction: &ExtractionConfig,
        auth: &AuthConfig,
        installation: Option<String>,
        pii: Option<&PipelineConfig>,
        compliance: Option<&ComplianceConfig>,
        review: Option<&ReviewConfig>,
        glossary: Option<&GlossaryConfig>,
    ) -> Self {
        Self {
            extraction: extraction.clone(),
            installation,
            pii: pii.cloned(),
            compliance: compliance.cloned(),
            review: review.cloned(),
            glossary: glossary.cloned(),
            auth: auth.clone(),
        }
    }

    #[php(getter)]
    pub fn get_extraction(&self) -> ExtractionConfig {
        self.extraction.clone()
    }
    #[php(name = "getExtraction")]
    pub fn read_extraction(&self) -> ExtractionConfig {
        self.get_extraction()
    }

    pub fn get_installation(&self) -> Option<String> {
        self.installation.clone().map(Into::into)
    }

    #[php(getter)]
    pub fn get_pii(&self) -> Option<PipelineConfig> {
        self.pii.clone().map(Into::into)
    }
    #[php(name = "getPii")]
    pub fn read_pii(&self) -> Option<PipelineConfig> {
        self.get_pii()
    }

    pub fn set_pii(&mut self, value: Option<&PipelineConfig>) {
        self.pii = value.map(|value| value.clone().into());
    }

    #[php(getter)]
    pub fn get_compliance(&self) -> Option<ComplianceConfig> {
        self.compliance.clone().map(Into::into)
    }
    #[php(name = "getCompliance")]
    pub fn read_compliance(&self) -> Option<ComplianceConfig> {
        self.get_compliance()
    }

    pub fn set_compliance(&mut self, value: Option<&ComplianceConfig>) {
        self.compliance = value.map(|value| value.clone().into());
    }

    #[php(getter)]
    pub fn get_review(&self) -> Option<ReviewConfig> {
        self.review.clone().map(Into::into)
    }
    #[php(name = "getReview")]
    pub fn read_review(&self) -> Option<ReviewConfig> {
        self.get_review()
    }

    pub fn set_review(&mut self, value: Option<&ReviewConfig>) {
        self.review = value.map(|value| value.clone().into());
    }

    #[php(getter)]
    pub fn get_glossary(&self) -> Option<GlossaryConfig> {
        self.glossary.clone().map(Into::into)
    }
    #[php(name = "getGlossary")]
    pub fn read_glossary(&self) -> Option<GlossaryConfig> {
        self.get_glossary()
    }

    pub fn set_glossary(&mut self, value: Option<&GlossaryConfig>) {
        self.glossary = value.map(|value| value.clone().into());
    }

    #[php(getter)]
    pub fn get_auth(&self) -> AuthConfig {
        self.auth.clone()
    }
    #[php(name = "getAuth")]
    pub fn read_auth(&self) -> AuthConfig {
        self.get_auth()
    }

    pub fn audit(&self) -> Option<AuditConfig> {
        #[allow(clippy::needless_update)]
            let core_self = hacienda::HaciendaConfig {
                extraction: self.extraction.clone().into(),
                installation: self.installation.as_deref().map(|s| match s { "LocalFull" | "localfull" => hacienda_installation::InstallationConfig::LocalFull(Default::default()),"TeamOnPremise" | "teamonpremise" => hacienda_installation::InstallationConfig::TeamOnPremise(Default::default()),other => {
        ext_php_rs::exception::PhpException::from_message(format!(
            "invalid value {other:?} for field 'installation' of InstallationConfig: expected one of [LocalFull, TeamOnPremise]"
        ))
        .throw();
        hacienda_installation::InstallationConfig::LocalFull(Default::default())
    }
     })
    ,
                pii: self.pii.clone().map(Into::into),
                compliance: self.compliance.clone().map(Into::into),
                review: self.review.clone().map(Into::into),
                glossary: self.glossary.clone().map(Into::into),
                auth: self.auth.clone().into(),
                ..Default::default()
            };
        core_self.audit().map(|v| v.clone().into())
    }
}

#[derive(Clone)]
#[php_class]
#[php(name = "Hacienda\\HaciendaFacade")]
pub struct HaciendaFacade {
    inner: Arc<hacienda::HaciendaFacade>,
}

#[php_impl]
impl HaciendaFacade {
    /// Attach the dossier-membership ACL that gates `RevealTicket` minting
    /// (issue #147: creating a ticket = `pii:reveal` **and** belonging to the dossier).
    ///
    /// Without an ACL configured, minting is refused (fail-closed) — see the
    /// `Self::dossier_acl` field doc.
    pub fn with_dossier_acl(&self, acl: &DossierAcl) -> HaciendaFacade {
        Self {
            inner: Arc::new((*self.inner).clone().with_dossier_acl(&acl.inner)),
        }
    }

    /// Attach the document→dossier index that proves every `document_id` of a ticket
    /// request belongs to the request's `dossier_id` (issue #147 ownership gate).
    ///
    /// Without an index configured, minting is refused (fail-closed) — see the
    /// `Self::document_dossier_index` field doc.
    pub fn with_document_dossier_index(&self, index: &DocumentDossierIndex) -> HaciendaFacade {
        Self {
            inner: Arc::new((*self.inner).clone().with_document_dossier_index(&index.inner)),
        }
    }

    /// Runtime identity of the NER detector this facade actually uses.
    ///
    /// Capability surfaces read this from their own facade so a report never
    /// claims a model another surface happened to load in the same process.
    pub fn ner_runtime_state(&self) -> NerRuntimeState {
        self.inner.ner_runtime_state().into()
    }

    pub fn config(&self) -> HaciendaConfig {
        self.inner.config().clone().into()
    }

    /// The queue holding detections that fell below the review threshold.
    pub fn review_queue(&self) -> Option<ReviewQueue> {
        self.inner.review_queue().map(|v| ReviewQueue {
            inner: Arc::new(v.clone()),
        })
    }

    /// Resolve a bearer token to its capability set.
    ///
    /// This is used by the auth middleware. The presented token is first looked up by
    /// its deterministic lookup digest (Argon2id's salted hash cannot serve as a lookup
    /// key — see the `auth::keys` module docs), then the match is confirmed with a full
    /// Argon2id `verify_key` check against the stored
    /// hash before any capability is granted. Returns `None` if the token is not found,
    /// fails verification, is revoked, or is malformed. The raw token is never stored —
    /// only its hashes.
    pub fn resolve_token(&self, bearerToken: String) -> Option<CapabilitySet> {
        let inner = self.inner.clone();
        let result = WORKER_RUNTIME.block_on(async { inner.resolve_token(&bearerToken).await });
        result.map(Into::into)
    }

    /// A snapshot of the open segment's audit entries.
    ///
    /// Returns only the open segment. For the full history across sealed segments,
    /// call the store's `seals()` and re-read the segment files directly.
    ///
    /// Returns an empty `Vec` when auditing is not configured — callers do not need to
    /// distinguish "no store" from "store with no entries yet".
    pub fn audit_entries(&self) -> PhpResult<Vec<AuditEntry>> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.audit_entries().await.map_err(alef_php_err)?;
            Ok(result.into_iter().map(Into::into).collect())
        })
    }

    /// The current head of the audit hash chain, or `None` when auditing is disabled.
    ///
    /// Every content-bearing API response carries this so a client can prove which chain
    /// state produced a given output. Deliberately not capability-guarded: the tip is an
    /// opaque hash that reveals nothing about the entries behind it, and gating it would
    /// mean a caller with `documents:process` but not `audit:read` could not obtain the
    /// evidence for its own result.
    ///
    /// `None` is honest rather than convenient: a client must be able to tell "auditing
    /// is off, this result has no chain evidence" from "the chain is empty".
    pub fn audit_tip(&self) -> PhpResult<Option<String>> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.audit_tip().await.map_err(alef_php_err)?;
            Ok(result)
        })
    }

    /// Whether an audit store is configured at all, independent of the caller's
    /// capabilities.
    ///
    /// Distinguishes "nothing failed" from "there is no chain to fail" — see
    /// `Self::verify_audit_with_auth`, which returns `Ok(())` in both cases and
    /// therefore cannot answer this on its own.
    pub fn audit_enabled(&self) -> bool {
        self.inner.audit_enabled()
    }

    /// Verify the audit chain has not been tampered with.
    ///
    /// A facade with no audit store configured trivially returns `Ok(())`. The
    /// verification is a no-op not because the chain was verified and found clean, but
    /// because there is no chain — callers that need a guarantee should assert that
    /// auditing is enabled before calling.
    ///
    /// # Errors
    ///
    /// Returns `HaciendaError::Audit` naming the first entry or seal whose hash does
    /// not match the chain.
    pub fn verify_audit(&self) -> PhpResult<()> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.verify_audit().await.map_err(alef_php_err)?;
            Ok(result)
        })
    }

    /// Shut down every store the facade holds: seal the audit segment and release the
    /// review store's resources.
    ///
    /// Calling `close` is recommended when the facade holds a `FileAuditStore`: it
    /// seals the open segment so the next process finds a clean chain with no unsealed
    /// orphan. If you skip `close`, recovery on the next open replays and seals the
    /// orphan automatically — so forgetting `close` loses no data. The difference is
    /// one extra recovery step on the next startup.
    ///
    /// `close` is idempotent: calling it more than once returns `Ok(())` on every
    /// subsequent call. When no stores are configured it is a no-op.
    ///
    /// # Why both stores are closed even if the first fails
    ///
    /// A failed audit seal must not leave a review store's resources held. Both closes
    /// are attempted and the first error is returned, so one broken backend cannot make
    /// the other leak.
    ///
    /// # Why not `Drop`
    ///
    /// `Drop` cannot `.await`. `block_on` inside `Drop` panics when called from within
    /// a Tokio runtime, and a detached `tokio::spawn` risks the process exiting before
    /// the write completes. Recovery is the correct backstop; `close` is the courtesy
    /// that avoids the extra startup work.
    ///
    /// # Multi-tenant caveat (S1b)
    ///
    /// Seals only `caller`'s own tenant's open segment — `AuditStore::close` takes a
    /// tenant and the store has no "every tenant that ever touched me" enumeration to
    /// close them all. A process serving several tenants that calls plain `close()`
    /// (which acts as `TenantId::default_tenant()` via `Caller::Trusted`) leaves every
    /// other tenant's segment unsealed at shutdown. That is not a data-loss gap — see
    /// the recovery note above — but it does mean a multi-tenant deployment that wants
    /// every chain sealed before exit must call `close_with_auth` once per tenant it has
    /// actually served, not just once. Tracked as a follow-up to close alongside this
    /// gap rather than solved here.
    ///
    /// # Errors
    ///
    /// Returns `HaciendaError::Audit` if the seal write fails, or
    /// `HaciendaError::Review` if the review store's cleanup fails.
    ///
    /// `FileAuditStore`: crate::audit::FileAuditStore
    pub fn close(&self) -> PhpResult<()> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.close().await.map_err(alef_php_err)?;
            Ok(result)
        })
    }

    /// Extract, detect, redact, audit, review, and generate compliance artefacts.
    ///
    /// # Errors
    ///
    /// Returns `HaciendaError::Extraction` if xberg cannot read the document and
    /// `HaciendaError::Pii` if detection fails. Detection failures are never
    /// downgraded to partial results: text that was not fully scanned must not be
    /// returned as if it had been redacted.
    pub fn process(&self, input: &ExtractInput) -> PhpResult<HaciendaResult> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.process(input.clone().into()).await.map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    /// Process several inputs as one extraction, sharing the audit chain and glossary.
    ///
    /// # Errors
    ///
    /// As `HaciendaFacade::process`.
    pub fn process_batch(&self, inputs: &ext_php_rs::types::ZendHashTable) -> PhpResult<HaciendaResult> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.process_batch(inputs_core).await.map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    /// Scan raw text for PII without modifying it.
    ///
    /// Convenience delegate that passes `Caller::Trusted`, mirroring the
    /// `process` / `process_with_auth` pairing. Use in-process tools such as
    /// the CLI where the process boundary is the trust boundary.
    ///
    /// # Errors
    ///
    /// Returns `HaciendaError::Pii` if PII detection is not enabled in the
    /// config (`pii` section absent) or if the detection pipeline fails.
    pub fn scan_text(&self, text: String, spanText: String) -> PhpResult<TextScanResult> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner
                .scan_text(
                    &text,
                    serde_json::from_str(&serde_json::to_string(&spanText).unwrap_or_default()).unwrap_or_default(),
                )
                .await
                .map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    /// Redact raw text without going through document extraction.
    ///
    /// Convenience delegate that passes `Caller::Trusted`.
    ///
    /// # Errors
    ///
    /// Returns `HaciendaError::Pii` if PII is not enabled or detection fails.
    pub fn redact_text(&self, text: String) -> PhpResult<TextRedactResult> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.redact_text(&text).await.map_err(alef_php_err)?;
            Ok(result.into())
        })
    }
}

