#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\HaciendaResult")]
#[serde(default)]
pub struct HaciendaResult {
    /// The extraction envelope. When PII is enabled, every document's `content` has
    /// already been redacted — the raw text never leaves this call.
    pub extraction: ExtractionResult,
    /// One detection result per extracted document, in the same order.
    pub pii: Vec<PipelineResult>,
    pub compliance: Option<ComplianceReport>,
    /// Audit entries appended by this call. The full chain lives in the facade.
    #[serde(alias = "auditEntries")]
    pub audit_entries: Vec<AuditEntry>,
    /// Detections routed to human review by this call.
    #[php(prop, name = "reviewSubmitted")]
    #[serde(alias = "reviewSubmitted")]
    pub review_submitted: i64,
    /// Glossary terms meeting the publication threshold, across every call so far.
    pub glossary: Vec<GlossaryEntry>,
    pub metadata: HaciendaMetadata,
}

#[php_impl]
impl HaciendaResult {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        extraction: &ExtractionResult,
        pii: &ext_php_rs::types::ZendHashTable,
        auditEntries: &ext_php_rs::types::ZendHashTable,
        reviewSubmitted: i64,
        glossary: &ext_php_rs::types::ZendHashTable,
        metadata: &HaciendaMetadata,
        compliance: Option<&ComplianceReport>,
    ) -> PhpResult<Self> {
        let mut pii_core_result: Vec<PipelineResult> = Vec::new();
        for (_, item) in pii.iter() {
            if let Some(parsed) = <&PipelineResult as ext_php_rs::convert::FromZval>::from_zval(item) {
                pii_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to PipelineResult".to_string(),
                ));
            }
        }
        let pii_core: Vec<PipelineResult> = pii_core_result;
        let mut auditEntries_core_result: Vec<AuditEntry> = Vec::new();
        for (_, item) in auditEntries.iter() {
            if let Some(parsed) = <&AuditEntry as ext_php_rs::convert::FromZval>::from_zval(item) {
                auditEntries_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to AuditEntry".to_string(),
                ));
            }
        }
        let auditEntries_core: Vec<AuditEntry> = auditEntries_core_result;
        let mut glossary_core_result: Vec<GlossaryEntry> = Vec::new();
        for (_, item) in glossary.iter() {
            if let Some(parsed) = <&GlossaryEntry as ext_php_rs::convert::FromZval>::from_zval(item) {
                glossary_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to GlossaryEntry".to_string(),
                ));
            }
        }
        let glossary_core: Vec<GlossaryEntry> = glossary_core_result;
        Ok(Self {
            extraction: extraction.clone(),
            pii: pii_core,
            compliance: compliance.cloned(),
            audit_entries: auditEntries_core,
            review_submitted: reviewSubmitted,
            glossary: glossary_core,
            metadata: metadata.clone(),
        })
    }

    #[php(getter)]
    pub fn get_extraction(&self) -> ExtractionResult {
        self.extraction.clone()
    }
    #[php(name = "getExtraction")]
    pub fn read_extraction(&self) -> ExtractionResult {
        self.get_extraction()
    }

    #[php(getter)]
    pub fn get_pii(&self) -> Vec<PipelineResult> {
        self.pii.clone()
    }
    #[php(name = "getPii")]
    pub fn read_pii(&self) -> Vec<PipelineResult> {
        self.get_pii()
    }

    #[php(getter)]
    pub fn get_compliance(&self) -> Option<ComplianceReport> {
        self.compliance.clone().map(Into::into)
    }
    #[php(name = "getCompliance")]
    pub fn read_compliance(&self) -> Option<ComplianceReport> {
        self.get_compliance()
    }

    pub fn set_compliance(&mut self, value: Option<&ComplianceReport>) {
        self.compliance = value.map(|value| value.clone().into());
    }

    #[php(getter)]
    pub fn get_audit_entries(&self) -> Vec<AuditEntry> {
        self.audit_entries.clone()
    }
    #[php(name = "getAuditEntries")]
    pub fn read_audit_entries(&self) -> Vec<AuditEntry> {
        self.get_audit_entries()
    }

    pub fn get_review_submitted(&self) -> i64 {
        self.review_submitted.clone()
    }

    #[php(getter)]
    pub fn get_glossary(&self) -> Vec<GlossaryEntry> {
        self.glossary.clone()
    }
    #[php(name = "getGlossary")]
    pub fn read_glossary(&self) -> Vec<GlossaryEntry> {
        self.get_glossary()
    }

    #[php(getter)]
    pub fn get_metadata(&self) -> HaciendaMetadata {
        self.metadata.clone()
    }
    #[php(name = "getMetadata")]
    pub fn read_metadata(&self) -> HaciendaMetadata {
        self.get_metadata()
    }
}

