#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\ImageMetadataType")]
#[serde(default)]
pub struct ImageMetadataType {
    /// Image source (URL, data URI, or SVG content)
    #[php(prop, name = "src")]
    pub src: String,
    /// Alternative text from alt attribute
    #[php(prop, name = "alt")]
    pub alt: Option<String>,
    /// Title attribute
    #[php(prop, name = "title")]
    pub title: Option<String>,
    /// Image dimensions if available.
    pub dimensions: Option<ImageDimensions>,
    /// Image type classification
    #[php(prop, name = "imageType")]
    #[serde(skip_serializing_if = "String::is_empty")]
    #[serde(alias = "imageType")]
    pub image_type: String,
    /// Additional attributes as key-value pairs.
    pub attributes: Vec<KeyValueAttribute>,
}

#[php_impl]
impl ImageMetadataType {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        src: String,
        imageType: String,
        attributes: &ext_php_rs::types::ZendHashTable,
        alt: Option<String>,
        title: Option<String>,
        dimensions: Option<&ImageDimensions>,
    ) -> PhpResult<Self> {
        let mut attributes_core_result: Vec<KeyValueAttribute> = Vec::new();
        for (_, item) in attributes.iter() {
            if let Some(parsed) = <&KeyValueAttribute as ext_php_rs::convert::FromZval>::from_zval(item) {
                attributes_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to KeyValueAttribute".to_string(),
                ));
            }
        }
        let attributes_core: Vec<KeyValueAttribute> = attributes_core_result;
        Ok(Self {
            src,
            alt,
            title,
            dimensions: dimensions.cloned(),
            image_type: imageType,
            attributes: attributes_core,
        })
    }

    pub fn get_src(&self) -> String {
        self.src.clone()
    }

    pub fn get_alt(&self) -> Option<String> {
        self.alt.clone()
    }

    pub fn get_title(&self) -> Option<String> {
        self.title.clone()
    }

    #[php(getter)]
    pub fn get_dimensions(&self) -> Option<ImageDimensions> {
        self.dimensions.clone().map(Into::into)
    }
    #[php(name = "getDimensions")]
    pub fn read_dimensions(&self) -> Option<ImageDimensions> {
        self.get_dimensions()
    }

    pub fn set_dimensions(&mut self, value: Option<&ImageDimensions>) {
        self.dimensions = value.map(|value| value.clone().into());
    }

    pub fn get_image_type(&self) -> String {
        self.image_type.clone()
    }

    #[php(getter)]
    pub fn get_attributes(&self) -> Vec<KeyValueAttribute> {
        self.attributes.clone()
    }
    #[php(name = "getAttributes")]
    pub fn read_attributes(&self) -> Vec<KeyValueAttribute> {
        self.get_attributes()
    }
}

