#[php_class]
#[php(name = "Hacienda\\JatsMetadata")]
#[serde(default)]
pub struct JatsMetadata {
    /// Copyright statement from the article's `<permissions>` element.
    #[php(prop, name = "copyright")]
    pub copyright: Option<String>,
    /// Open-access license URI from the article's `<license>` element.
    #[php(prop, name = "license")]
    pub license: Option<String>,
    /// Publication history dates keyed by event type (e.g. `"received"`, `"accepted"`).
    #[php(prop, name = "historyDates")]
    #[serde(alias = "historyDates")]
    #[serde(default)]
    pub history_dates: HashMap<String, String>,
    /// Authors and contributors with their stated roles.
    #[serde(alias = "contributorRoles")]
    #[serde(default)]
    pub contributor_roles: Vec<ContributorRole>,
}

impl Default for JatsMetadata {
    fn default() -> Self {
        <xberg::JatsMetadata as Default>::default().into()
    }
}

#[php_impl]
impl JatsMetadata {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        historyDates: HashMap<String, String>,
        contributorRoles: &ext_php_rs::types::ZendHashTable,
        copyright: Option<String>,
        license: Option<String>,
    ) -> PhpResult<Self> {
        let mut contributorRoles_core_result: Vec<ContributorRole> = Vec::new();
        for (_, item) in contributorRoles.iter() {
            if let Some(parsed) = <&ContributorRole as ext_php_rs::convert::FromZval>::from_zval(item) {
                contributorRoles_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to ContributorRole".to_string(),
                ));
            }
        }
        let contributorRoles_core: Vec<ContributorRole> = contributorRoles_core_result;
        Ok(Self {
            copyright,
            license,
            history_dates: historyDates,
            contributor_roles: contributorRoles_core,
        })
    }

    pub fn get_copyright(&self) -> Option<String> {
        self.copyright.clone()
    }

    pub fn get_license(&self) -> Option<String> {
        self.license.clone()
    }

    pub fn get_history_dates(&self) -> HashMap<String, String> {
        self.history_dates.clone()
    }

    #[php(getter)]
    pub fn get_contributor_roles(&self) -> Vec<ContributorRole> {
        self.contributor_roles.clone()
    }
    #[php(name = "getContributorRoles")]
    pub fn read_contributor_roles(&self) -> Vec<ContributorRole> {
        self.get_contributor_roles()
    }
}

