#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\OcrPipelineConfig")]
#[serde(default)]
pub struct OcrPipelineConfig {
    /// Ordered list of backends to try. Sorted by priority (descending) at runtime.
    pub stages: Vec<OcrPipelineStage>,
    /// Quality thresholds for deciding whether to accept a result or try the next backend.
    #[serde(alias = "qualityThresholds")]
    #[serde(default)]
    pub quality_thresholds: OcrQualityThresholds,
}

#[php_impl]
impl OcrPipelineConfig {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(stages: &ext_php_rs::types::ZendHashTable, qualityThresholds: &OcrQualityThresholds) -> PhpResult<Self> {
        let mut stages_core_result: Vec<OcrPipelineStage> = Vec::new();
        for (_, item) in stages.iter() {
            if let Some(parsed) = <&OcrPipelineStage as ext_php_rs::convert::FromZval>::from_zval(item) {
                stages_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to OcrPipelineStage".to_string(),
                ));
            }
        }
        let stages_core: Vec<OcrPipelineStage> = stages_core_result;
        Ok(Self {
            stages: stages_core,
            quality_thresholds: qualityThresholds.clone(),
        })
    }

    #[php(getter)]
    pub fn get_stages(&self) -> Vec<OcrPipelineStage> {
        self.stages.clone()
    }
    #[php(name = "getStages")]
    pub fn read_stages(&self) -> Vec<OcrPipelineStage> {
        self.get_stages()
    }

    #[php(getter)]
    pub fn get_quality_thresholds(&self) -> OcrQualityThresholds {
        self.quality_thresholds.clone()
    }
    #[php(name = "getQualityThresholds")]
    pub fn read_quality_thresholds(&self) -> OcrQualityThresholds {
        self.get_quality_thresholds()
    }
}

#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\OcrPipelineStage")]
#[serde(default)]
pub struct OcrPipelineStage {
    /// Backend name: "tesseract", "paddleocr", "paddle-ocr", "sceptre", "vlm", or a custom registered name.
    /// Sceptre uses ONNX Runtime on desktop/server and tract on Android/iOS; browser WebAssembly has a separate
    /// byte-fed engine because the normal async OCR registry assumes native model storage.
    #[php(prop, name = "backend")]
    pub backend: String,
    /// Priority weight (higher = tried first). Stages are sorted by priority descending.
    #[php(prop, name = "priority")]
    pub priority: u32,
    /// Language override for this stage (undefined = use parent OcrConfig.language).
    ///
    /// A list is the canonical form and the only form accepted by the binding
    /// object APIs: `["eng", "deu"]`. When deserializing from a config file,
    /// JSON body, or the REST/MCP API, a single string is also accepted,
    /// either as one code ("eng") or "+"-joined ("eng+deu").
    #[php(prop, name = "language")]
    #[serde(default)]
    pub language: Option<Vec<String>>,
    /// Legacy PaddleOCR config JSON for this stage.
    ///
    /// Deprecated since 1.3.2 and planned for removal in 2.0. Use
    /// `Self.paddle_ocr_settings` for typed access.
    #[serde(alias = "paddleOcrConfig")]
    #[serde(default)]
    pub paddle_ocr_config: Option<serde_json::Value>,
    /// Typed PaddleOCR config for this stage.
    ///
    /// When both PaddleOCR fields are set, this typed field takes precedence.
    #[serde(alias = "paddleOcrSettings")]
    #[serde(default)]
    pub paddle_ocr_settings: Option<PaddleOcrConfig>,
    /// VLM config override for this pipeline stage.
    #[serde(alias = "vlmConfig")]
    #[serde(default)]
    pub vlm_config: Option<LlmConfig>,
    /// Arbitrary per-call options passed through to the backend unchanged.
    ///
    /// Backends that support runtime tuning (mode switching, preprocessing
    /// flags, inference parameters, etc.) read this value and deserialize
    /// the keys they care about. Keys unknown to the backend are silently
    /// ignored, so options from different backends can coexist in the same
    /// config without conflict.
    ///
    /// Example (custom backend):
    /// ```json
    /// { "mode": "fast", "enable_layout": true }
    /// ```
    #[serde(alias = "backendOptions")]
    #[serde(default)]
    pub backend_options: Option<serde_json::Value>,
}

#[php_impl]
impl OcrPipelineStage {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        backend: String,
        priority: u32,
        language: Option<Vec<String>>,
        paddleOcrConfig: Option<String>,
        paddleOcrSettings: Option<&PaddleOcrConfig>,
        vlmConfig: Option<&LlmConfig>,
        backendOptions: Option<String>,
    ) -> PhpResult<Self> {
        Ok(Self {
            backend,
            priority,
            language,
            paddle_ocr_config: paddleOcrConfig
                .map(|s| serde_json::from_str(&s))
                .transpose()
                .map_err(|e| PhpException::from_message(e.to_string()))?,
            paddle_ocr_settings: paddleOcrSettings.cloned(),
            vlm_config: vlmConfig.cloned(),
            backend_options: backendOptions
                .map(|s| serde_json::from_str(&s))
                .transpose()
                .map_err(|e| PhpException::from_message(e.to_string()))?,
        })
    }

    pub fn get_backend(&self) -> String {
        self.backend.clone()
    }

    pub fn get_priority(&self) -> u32 {
        self.priority.clone()
    }

    pub fn get_language(&self) -> Option<Vec<String>> {
        self.language.clone()
    }

    #[php(getter)]
    pub fn get_paddle_ocr_config(&self) -> Option<String> {
        self.paddle_ocr_config.as_ref().and_then(|v| {
            serde_json::to_value(v).ok().and_then(|json| match json {
                serde_json::Value::String(text) => Some(text),
                other => serde_json::to_string(&other).ok(),
            })
        })
    }
    #[php(name = "getPaddleOcrConfig")]
    pub fn read_paddle_ocr_config(&self) -> Option<String> {
        self.get_paddle_ocr_config()
    }

    #[php(getter)]
    pub fn get_paddle_ocr_settings(&self) -> Option<PaddleOcrConfig> {
        self.paddle_ocr_settings.clone().map(Into::into)
    }
    #[php(name = "getPaddleOcrSettings")]
    pub fn read_paddle_ocr_settings(&self) -> Option<PaddleOcrConfig> {
        self.get_paddle_ocr_settings()
    }

    pub fn set_paddle_ocr_settings(&mut self, value: Option<&PaddleOcrConfig>) {
        self.paddle_ocr_settings = value.map(|value| value.clone().into());
    }

    #[php(getter)]
    pub fn get_vlm_config(&self) -> Option<LlmConfig> {
        self.vlm_config.clone().map(Into::into)
    }
    #[php(name = "getVlmConfig")]
    pub fn read_vlm_config(&self) -> Option<LlmConfig> {
        self.get_vlm_config()
    }

    pub fn set_vlm_config(&mut self, value: Option<&LlmConfig>) {
        self.vlm_config = value.map(|value| value.clone().into());
    }

    #[php(getter)]
    pub fn get_backend_options(&self) -> Option<String> {
        self.backend_options.as_ref().and_then(|v| {
            serde_json::to_value(v).ok().and_then(|json| match json {
                serde_json::Value::String(text) => Some(text),
                other => serde_json::to_string(&other).ok(),
            })
        })
    }
    #[php(name = "getBackendOptions")]
    pub fn read_backend_options(&self) -> Option<String> {
        self.get_backend_options()
    }
}

