#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\PageClassification")]
#[serde(default)]
pub struct PageClassification {
    /// 1-indexed page number this classification belongs to.
    #[php(prop, name = "pageNumber")]
    #[serde(alias = "pageNumber")]
    pub page_number: u32,
    /// Labels assigned to the page. Single-label classification yields exactly one
    /// entry; multi-label classification yields any subset of the configured label set.
    pub labels: Vec<ClassificationLabel>,
}

#[php_impl]
impl PageClassification {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(pageNumber: u32, labels: &ext_php_rs::types::ZendHashTable) -> PhpResult<Self> {
        let mut labels_core_result: Vec<ClassificationLabel> = Vec::new();
        for (_, item) in labels.iter() {
            if let Some(parsed) = <&ClassificationLabel as ext_php_rs::convert::FromZval>::from_zval(item) {
                labels_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to ClassificationLabel".to_string(),
                ));
            }
        }
        let labels_core: Vec<ClassificationLabel> = labels_core_result;
        Ok(Self {
            page_number: pageNumber,
            labels: labels_core,
        })
    }

    pub fn get_page_number(&self) -> u32 {
        self.page_number.clone()
    }

    #[php(getter)]
    pub fn get_labels(&self) -> Vec<ClassificationLabel> {
        self.labels.clone()
    }
    #[php(name = "getLabels")]
    pub fn read_labels(&self) -> Vec<ClassificationLabel> {
        self.get_labels()
    }
}

