#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\PageContent")]
#[serde(default)]
pub struct PageContent {
    /// Page number (1-indexed)
    #[php(prop, name = "pageNumber")]
    #[serde(alias = "pageNumber")]
    pub page_number: u32,
    /// Text content for this page
    #[php(prop, name = "content")]
    pub content: String,
    /// Tables found on this page (uses Arc for memory efficiency)
    ///
    /// Serializes as `Vec<Table>` for JSON compatibility while maintaining
    /// Arc semantics in-memory for zero-copy sharing.
    #[serde(default)]
    pub tables: Vec<Table>,
    /// Indices into `ExtractedDocument.images` for images found on this page.
    ///
    /// Each value is a zero-based index into the top-level `images` collection.
    /// Only populated when `extract_images = true` in the extraction config.
    #[php(prop, name = "imageIndices")]
    #[serde(alias = "imageIndices")]
    #[serde(default)]
    pub image_indices: Vec<u32>,
    /// OCR image preprocessing applied to this page's raster.
    #[serde(alias = "imagePreprocessing")]
    #[serde(default)]
    pub image_preprocessing: Option<ImagePreprocessingMetadata>,
    /// Hierarchy information for the page (when hierarchy extraction is enabled)
    ///
    /// Contains text hierarchy levels (H1-H6) extracted from the page content.
    pub hierarchy: Option<PageHierarchy>,
    /// Whether this page is blank (no meaningful text content)
    ///
    /// Determined during extraction based on text content analysis.
    /// A page is blank if it has fewer than 3 non-whitespace characters
    /// and contains no tables or images.
    #[php(prop, name = "isBlank")]
    #[serde(alias = "isBlank")]
    pub is_blank: Option<bool>,
    /// Layout detection regions for this page (when layout detection is enabled).
    ///
    /// Contains detected layout regions with class, confidence, bounding box,
    /// and area fraction. Only populated when layout detection is configured.
    #[serde(alias = "layoutRegions")]
    pub layout_regions: Option<Vec<LayoutRegion>>,
    /// Speaker notes for this slide (PPTX only).
    ///
    /// Contains the text from the slide's notes pane (`ppt/notesSlides/notesSlide{N}.xml`).
    /// Only populated when the source is a PPTX file and notes are present.
    #[php(prop, name = "speakerNotes")]
    #[serde(alias = "speakerNotes")]
    pub speaker_notes: Option<String>,
    /// Section name this slide belongs to (PPTX only).
    ///
    /// PowerPoint sections group slides into logical chapters (`<p:sectionLst>` in
    /// `ppt/presentation.xml`). Only populated when the source is a PPTX file and
    /// the slide belongs to a named section.
    #[php(prop, name = "sectionName")]
    #[serde(alias = "sectionName")]
    pub section_name: Option<String>,
    /// Sheet name for this page (XLSX/ODS only).
    ///
    /// Each spreadsheet sheet maps to one `PageContent` entry. This field carries the
    /// sheet's display name as it appears in the workbook. `None` for all non-spreadsheet
    /// formats and for sheets with an empty name.
    #[php(prop, name = "sheetName")]
    #[serde(alias = "sheetName")]
    pub sheet_name: Option<String>,
    /// Aggregate OCR confidence for this page. `None` when the page was not OCR'd.
    #[serde(alias = "ocrConfidence")]
    #[serde(default)]
    pub ocr_confidence: Option<PageOcrConfidence>,
    /// Text layer of this page, kept when OCR output replaced it in `content`.
    ///
    /// Set only when `PageConfig.keep_native_content` is on, an OCR route replaced this page's `content`, and the
    /// text layer is not blank and differs from the OCR text. `None` on every other page. PDF only.
    #[php(prop, name = "nativeContent")]
    #[serde(alias = "nativeContent")]
    #[serde(default)]
    pub native_content: Option<String>,
}

#[php_impl]
impl PageContent {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        pageNumber: u32,
        content: String,
        tables: &ext_php_rs::types::ZendHashTable,
        imageIndices: Vec<u32>,
        imagePreprocessing: Option<&ImagePreprocessingMetadata>,
        hierarchy: Option<&PageHierarchy>,
        isBlank: Option<bool>,
        layoutRegions: Option<&ext_php_rs::types::ZendHashTable>,
        speakerNotes: Option<String>,
        sectionName: Option<String>,
        sheetName: Option<String>,
        ocrConfidence: Option<&PageOcrConfidence>,
        nativeContent: Option<String>,
    ) -> PhpResult<Self> {
        let mut tables_core_result: Vec<Table> = Vec::new();
        for (_, item) in tables.iter() {
            if let Some(parsed) = <&Table as ext_php_rs::convert::FromZval>::from_zval(item) {
                tables_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to Table".to_string(),
                ));
            }
        }
        let tables_core: Vec<Table> = tables_core_result;
        let layoutRegions_core: Option<Vec<LayoutRegion>> = if let Some(ht) = layoutRegions {
            let mut result = Vec::new();
            for (_, item) in ht.iter() {
                if let Some(parsed) = <&LayoutRegion as ext_php_rs::convert::FromZval>::from_zval(item) {
                    result.push(parsed.clone());
                } else {
                    return Err(ext_php_rs::exception::PhpException::from_message(
                        "Failed to convert array element to LayoutRegion".to_string(),
                    ));
                }
            }
            Some(result)
        } else {
            None
        };
        Ok(Self {
            page_number: pageNumber,
            content,
            tables: tables_core,
            image_indices: imageIndices,
            image_preprocessing: imagePreprocessing.cloned(),
            hierarchy: hierarchy.cloned(),
            is_blank: isBlank,
            layout_regions: layoutRegions_core,
            speaker_notes: speakerNotes,
            section_name: sectionName,
            sheet_name: sheetName,
            ocr_confidence: ocrConfidence.cloned(),
            native_content: nativeContent,
        })
    }

    pub fn get_page_number(&self) -> u32 {
        self.page_number.clone()
    }

    pub fn get_content(&self) -> String {
        self.content.clone()
    }

    #[php(getter)]
    pub fn get_tables(&self) -> Vec<Table> {
        self.tables.clone()
    }
    #[php(name = "getTables")]
    pub fn read_tables(&self) -> Vec<Table> {
        self.get_tables()
    }

    pub fn get_image_indices(&self) -> Vec<u32> {
        self.image_indices.clone()
    }

    #[php(getter)]
    pub fn get_image_preprocessing(&self) -> Option<ImagePreprocessingMetadata> {
        self.image_preprocessing.clone().map(Into::into)
    }
    #[php(name = "getImagePreprocessing")]
    pub fn read_image_preprocessing(&self) -> Option<ImagePreprocessingMetadata> {
        self.get_image_preprocessing()
    }

    pub fn set_image_preprocessing(&mut self, value: Option<&ImagePreprocessingMetadata>) {
        self.image_preprocessing = value.map(|value| value.clone().into());
    }

    #[php(getter)]
    pub fn get_hierarchy(&self) -> Option<PageHierarchy> {
        self.hierarchy.clone().map(Into::into)
    }
    #[php(name = "getHierarchy")]
    pub fn read_hierarchy(&self) -> Option<PageHierarchy> {
        self.get_hierarchy()
    }

    pub fn set_hierarchy(&mut self, value: Option<&PageHierarchy>) {
        self.hierarchy = value.map(|value| value.clone().into());
    }

    pub fn get_is_blank(&self) -> Option<bool> {
        self.is_blank.clone()
    }

    #[php(getter)]
    pub fn get_layout_regions(&self) -> Option<Vec<LayoutRegion>> {
        self.layout_regions.clone()
    }
    #[php(name = "getLayoutRegions")]
    pub fn read_layout_regions(&self) -> Option<Vec<LayoutRegion>> {
        self.get_layout_regions()
    }

    pub fn get_speaker_notes(&self) -> Option<String> {
        self.speaker_notes.clone()
    }

    pub fn get_section_name(&self) -> Option<String> {
        self.section_name.clone()
    }

    pub fn get_sheet_name(&self) -> Option<String> {
        self.sheet_name.clone()
    }

    #[php(getter)]
    pub fn get_ocr_confidence(&self) -> Option<PageOcrConfidence> {
        self.ocr_confidence.clone().map(Into::into)
    }
    #[php(name = "getOcrConfidence")]
    pub fn read_ocr_confidence(&self) -> Option<PageOcrConfidence> {
        self.get_ocr_confidence()
    }

    pub fn set_ocr_confidence(&mut self, value: Option<&PageOcrConfidence>) {
        self.ocr_confidence = value.map(|value| value.clone().into());
    }

    pub fn get_native_content(&self) -> Option<String> {
        self.native_content.clone()
    }
}

