#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\PageStructure")]
#[serde(default)]
pub struct PageStructure {
    /// Total number of pages/slides/sheets
    #[php(prop, name = "totalCount")]
    #[serde(alias = "totalCount")]
    pub total_count: u32,
    /// Type of paginated unit
    #[php(prop, name = "unitType")]
    #[serde(skip_serializing_if = "String::is_empty")]
    #[serde(alias = "unitType")]
    pub unit_type: String,
    /// Character offset boundaries for each page
    ///
    /// Maps character ranges in the extracted content to page numbers.
    /// Used for chunk page range calculation.
    pub boundaries: Option<Vec<PageBoundary>>,
    /// Detailed per-page metadata (optional, only when needed)
    pub pages: Option<Vec<PageInfo>>,
}

#[php_impl]
impl PageStructure {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        totalCount: u32,
        unitType: String,
        boundaries: Option<&ext_php_rs::types::ZendHashTable>,
        pages: Option<&ext_php_rs::types::ZendHashTable>,
    ) -> PhpResult<Self> {
        let boundaries_core: Option<Vec<PageBoundary>> = if let Some(ht) = boundaries {
            let mut result = Vec::new();
            for (_, item) in ht.iter() {
                if let Some(parsed) = <&PageBoundary as ext_php_rs::convert::FromZval>::from_zval(item) {
                    result.push(parsed.clone());
                } else {
                    return Err(ext_php_rs::exception::PhpException::from_message(
                        "Failed to convert array element to PageBoundary".to_string(),
                    ));
                }
            }
            Some(result)
        } else {
            None
        };
        let pages_core: Option<Vec<PageInfo>> = if let Some(ht) = pages {
            let mut result = Vec::new();
            for (_, item) in ht.iter() {
                if let Some(parsed) = <&PageInfo as ext_php_rs::convert::FromZval>::from_zval(item) {
                    result.push(parsed.clone());
                } else {
                    return Err(ext_php_rs::exception::PhpException::from_message(
                        "Failed to convert array element to PageInfo".to_string(),
                    ));
                }
            }
            Some(result)
        } else {
            None
        };
        Ok(Self {
            total_count: totalCount,
            unit_type: unitType,
            boundaries: boundaries_core,
            pages: pages_core,
        })
    }

    pub fn get_total_count(&self) -> u32 {
        self.total_count.clone()
    }

    pub fn get_unit_type(&self) -> String {
        self.unit_type.clone()
    }

    #[php(getter)]
    pub fn get_boundaries(&self) -> Option<Vec<PageBoundary>> {
        self.boundaries.clone()
    }
    #[php(name = "getBoundaries")]
    pub fn read_boundaries(&self) -> Option<Vec<PageBoundary>> {
        self.get_boundaries()
    }

    #[php(getter)]
    pub fn get_pages(&self) -> Option<Vec<PageInfo>> {
        self.pages.clone()
    }
    #[php(name = "getPages")]
    pub fn read_pages(&self) -> Option<Vec<PageInfo>> {
        self.get_pages()
    }
}

#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\PatternMeta")]
#[serde(default)]
pub struct PatternMeta {
    pub category: PiiCategory,
    #[php(prop, name = "pattern")]
    pub pattern: String,
    #[php(prop, name = "formatPreserving")]
    #[serde(alias = "formatPreserving")]
    pub format_preserving: bool,
    #[php(prop, name = "redactTemplate")]
    #[serde(alias = "redactTemplate")]
    pub redact_template: String,
    /// Confidence a match gets when `validator` is absent, or returns
    /// `None` (no opinion). Defaults to `1.0` via `PatternMeta.new` so every pre-existing
    /// pattern keeps today's behavior; only patterns with a real checksum
    /// (`validators`) set this lower, since an unvalidated match in those
    /// categories is genuinely less certain than a plain regex hit.
    #[php(prop, name = "baseConfidence")]
    #[serde(alias = "baseConfidence")]
    pub base_confidence: f32,
    /// Words that, found near a match, boost its confidence toward `1.0`
    /// (`context`). Empty for patterns with no calibrated context word list.
    #[php(prop, name = "contextWords")]
    #[serde(alias = "contextWords")]
    pub context_words: Vec<String>,
}

#[php_impl]
impl PatternMeta {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        category: &PiiCategory,
        pattern: String,
        formatPreserving: bool,
        redactTemplate: String,
        baseConfidence: f32,
        contextWords: Vec<String>,
    ) -> Self {
        Self {
            category: category.clone(),
            pattern,
            format_preserving: formatPreserving,
            redact_template: redactTemplate,
            base_confidence: baseConfidence,
            context_words: contextWords,
        }
    }

    #[php(getter)]
    pub fn get_category(&self) -> PiiCategory {
        self.category.clone()
    }
    #[php(name = "getCategory")]
    pub fn read_category(&self) -> PiiCategory {
        self.get_category()
    }

    pub fn get_pattern(&self) -> String {
        self.pattern.clone()
    }

    pub fn get_format_preserving(&self) -> bool {
        self.format_preserving.clone()
    }

    pub fn get_redact_template(&self) -> String {
        self.redact_template.clone()
    }

    pub fn get_base_confidence(&self) -> f32 {
        self.base_confidence.clone()
    }

    pub fn get_context_words(&self) -> Vec<String> {
        self.context_words.clone()
    }

    pub fn with_base_confidence(&self, baseConfidence: f32) -> PatternMeta {
        let core_self = hacienda::pii::PatternMeta {
            category: self.category.clone().into(),
            pattern: self.pattern.clone(),
            format_preserving: self.format_preserving,
            redact_template: self.redact_template.clone(),
            base_confidence: self.base_confidence,
            validator: Default::default(),
            context_words: self.context_words.clone(),
        };
        core_self.with_base_confidence(baseConfidence).into()
    }
}

