#[derive(Clone)]
#[php_class]
#[php(name = "Hacienda\\PiiPipeline")]
pub struct PiiPipeline {
    inner: Arc<hacienda::pii::PiiPipeline>,
}

#[php_impl]
impl PiiPipeline {
    pub fn config(&self) -> PipelineConfig {
        self.inner.config().clone().into()
    }

    /// True when a NER backend is loaded. A `false` here means regex-only detection.
    pub fn has_model(&self) -> bool {
        self.inner.has_model()
    }

    /// Detect and redact.
    ///
    /// # Errors
    ///
    /// Returns `PiiError::Ner` if the NER backend fails. Detection failures are not
    /// swallowed: returning partially-detected text as if it were redacted would leak PII.
    pub fn process(&self, text: String) -> PhpResult<PipelineResult> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.process(&text).await.map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    /// Detect without rewriting the text.
    ///
    /// # Errors
    ///
    /// Returns `PiiError::Ner` if the NER backend fails.
    pub fn scan(&self, text: String) -> PhpResult<PipelineResult> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner.scan(&text).await.map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    /// Detect and redact using pre-computed model entities, bypassing the NER detector.
    ///
    /// This allows callers who have already run NER inference (e.g., for an entity glossary)
    /// to reuse those results instead of running inference a second time.
    ///
    /// # Errors
    ///
    /// Returns `PiiError::Ner` if regex detection fails, or
    /// `PiiError::InvalidModelEntity` if any pre-computed model entity fails
    /// validation (see `validate_model_entity`).
    pub fn process_with_model_entities(
        &self,
        text: String,
        modelEntities: &ext_php_rs::types::ZendHashTable,
    ) -> PhpResult<PipelineResult> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner
                .process_with_model_entities(&text, modelEntities_core)
                .await
                .map_err(alef_php_err)?;
            Ok(result.into())
        })
    }

    /// Detect without rewriting the text, using pre-computed model entities.
    ///
    /// See `process_with_model_entities` for details.
    pub fn scan_with_model_entities(
        &self,
        text: String,
        modelEntities: &ext_php_rs::types::ZendHashTable,
    ) -> PhpResult<PipelineResult> {
        let inner = self.inner.clone();
        WORKER_RUNTIME.block_on(async {
            let result = inner
                .scan_with_model_entities(&text, modelEntities_core)
                .await
                .map_err(alef_php_err)?;
            Ok(result.into())
        })
    }
}

#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "Hacienda\\PipelineConfig")]
#[serde(default)]
pub struct PipelineConfig {
    /// Prefer deterministic regex spans over model spans when the two overlap.
    #[php(prop, name = "regexFirst")]
    #[serde(default = "crate::serde_defaults::pipeline_config_regex_first")]
    #[serde(alias = "regexFirst")]
    pub regex_first: bool,
    /// Model detections scoring below this are discarded before merging.
    #[php(prop, name = "modelThresholdDefault")]
    #[serde(default = "crate::serde_defaults::pipeline_config_model_threshold_default")]
    #[serde(alias = "modelThresholdDefault")]
    pub model_threshold_default: f32,
    /// Per-category threshold overrides — when a category is present here its value
    /// is used instead of `model_threshold_default`. Empty (default) means
    /// `effective_threshold` applies the hybrid persona-boost table.
    #[doc = "PHP: initialize this field through fromJson() and read it via get_model_thresholds(); its value type cannot be
exposed as a directly settable ext-php-rs property."]
    #[serde(alias = "modelThresholds")]
    pub model_thresholds: HashMap<PiiCategory, f32>,
    /// Overlap ratio above which two spans are treated as the same detection.
    #[php(prop, name = "mergeOverlapThreshold")]
    #[serde(default = "crate::serde_defaults::pipeline_config_merge_overlap_threshold")]
    #[serde(alias = "mergeOverlapThreshold")]
    pub merge_overlap_threshold: f32,
    pub redaction: RedactionConfig,
    pub audit: AuditConfig,
    pub model: ModelConfig,
    /// How many documents `process_batch_with_auth` runs
    /// through this pipeline at once.
    ///
    /// `1` is the default and preserves the pipeline's original strictly-sequential
    /// behaviour. Raising it bounds a worker pool over the batch's documents — it does
    /// not change what is returned: results still come back in input order (see
    /// `HaciendaResult.pii`) and every document is still audited and reviewed exactly
    /// once, regardless of completion order.
    #[php(prop, name = "concurrency")]
    #[serde(default = "crate::serde_defaults::pipeline_config_concurrency")]
    pub concurrency: i64,
    /// The Tier 0 schema vertical bound to this pipeline, if any.
    ///
    /// `None` (the default) is a strict no-op: nothing about detection changes unless
    /// an operator explicitly writes a `[pii.vertical]` section. See
    /// `superpowers/specs/2026-07-31-vertical-model-specialisation-design.md` §4.1 and
    /// `VerticalConfig`.
    ///
    /// There is deliberately no `verticals` array or selector — one optional vertical,
    /// bound at pipeline construction. A registry is premature abstraction at N=1; see
    /// the implementation plan's "Explicit Non-Goals".
    pub vertical: Option<VerticalConfig>,
}

