#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "Hacienda\\PipelineResult")]
#[serde(default)]
pub struct PipelineResult {
    /// Input text with every merged span rewritten. Equal to the input for `PiiPipeline.scan`.
    #[php(prop, name = "redactedText")]
    #[serde(alias = "redactedText")]
    pub redacted_text: String,
    pub entities: Vec<MergedEntity>,
    #[serde(alias = "auditLog")]
    pub audit_log: Vec<RedactionAuditEntry>,
    pub metrics: PipelineMetrics,
}

impl Default for PipelineResult {
    fn default() -> Self {
        <hacienda::pii::PipelineResult as Default>::default().into()
    }
}

#[php_impl]
impl PipelineResult {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        redactedText: String,
        entities: &ext_php_rs::types::ZendHashTable,
        auditLog: &ext_php_rs::types::ZendHashTable,
        metrics: &PipelineMetrics,
    ) -> PhpResult<Self> {
        let mut entities_core_result: Vec<MergedEntity> = Vec::new();
        for (_, item) in entities.iter() {
            if let Some(parsed) = <&MergedEntity as ext_php_rs::convert::FromZval>::from_zval(item) {
                entities_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to MergedEntity".to_string(),
                ));
            }
        }
        let entities_core: Vec<MergedEntity> = entities_core_result;
        let mut auditLog_core_result: Vec<RedactionAuditEntry> = Vec::new();
        for (_, item) in auditLog.iter() {
            if let Some(parsed) = <&RedactionAuditEntry as ext_php_rs::convert::FromZval>::from_zval(item) {
                auditLog_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to RedactionAuditEntry".to_string(),
                ));
            }
        }
        let auditLog_core: Vec<RedactionAuditEntry> = auditLog_core_result;
        Ok(Self {
            redacted_text: redactedText,
            entities: entities_core,
            audit_log: auditLog_core,
            metrics: metrics.clone(),
        })
    }

    pub fn get_redacted_text(&self) -> String {
        self.redacted_text.clone()
    }

    #[php(getter)]
    pub fn get_entities(&self) -> Vec<MergedEntity> {
        self.entities.clone()
    }
    #[php(name = "getEntities")]
    pub fn read_entities(&self) -> Vec<MergedEntity> {
        self.get_entities()
    }

    #[php(getter)]
    pub fn get_audit_log(&self) -> Vec<RedactionAuditEntry> {
        self.audit_log.clone()
    }
    #[php(name = "getAuditLog")]
    pub fn read_audit_log(&self) -> Vec<RedactionAuditEntry> {
        self.get_audit_log()
    }

    #[php(getter)]
    pub fn get_metrics(&self) -> PipelineMetrics {
        self.metrics.clone()
    }
    #[php(name = "getMetrics")]
    pub fn read_metrics(&self) -> PipelineMetrics {
        self.get_metrics()
    }
}

