#[serde(default)]
pub struct RedactionConfig {
    #[php(prop, name = "mode")]
    #[serde(skip_serializing_if = "String::is_empty")]
    pub mode: String,
    /// Template used when `mode` is `RedactionMode.Custom`.
    ///
    /// `{{ENTITY}}` expands to the category name and `{{TEXT}}` to the original span.
    #[php(prop, name = "customTemplate")]
    #[serde(alias = "customTemplate")]
    pub custom_template: Option<String>,
    /// Keep the shape of the original span (length, separators) where the mode allows it.
    #[php(prop, name = "preserveFormat")]
    #[serde(default = "crate::serde_defaults::redaction_config_preserve_format")]
    #[serde(alias = "preserveFormat")]
    pub preserve_format: bool,
    /// Which pseudonymisation key new tokens are minted under, when `mode` is
    /// `RedactionMode.Pseudonymize`. `None` means "whichever key the resolver reports
    /// as active".
    ///
    /// This is an *identifier*, never key material. The struct is serialised and printed
    /// by `config show`; putting a secret in it would put that secret in every dumped
    /// config, log line, and support bundle. Key material reaches the engine only through
    /// a `KeyResolver`.
    #[php(prop, name = "keyId")]
    #[serde(alias = "keyId")]
    #[serde(default)]
    pub key_id: Option<String>,
}

impl Default for RedactionConfig {
    fn default() -> Self {
        <hacienda::redaction::RedactionConfig as Default>::default().into()
    }
}

#[php_impl]
impl RedactionConfig {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(mode: String, preserveFormat: bool, customTemplate: Option<String>, keyId: Option<String>) -> Self {
        Self {
            mode,
            custom_template: customTemplate,
            preserve_format: preserveFormat,
            key_id: keyId,
        }
    }

    pub fn get_mode(&self) -> String {
        self.mode.clone()
    }

    pub fn get_custom_template(&self) -> Option<String> {
        self.custom_template.clone()
    }

    pub fn get_preserve_format(&self) -> bool {
        self.preserve_format.clone()
    }

    pub fn get_key_id(&self) -> Option<String> {
        self.key_id.clone()
    }

    #[allow(clippy::should_implement_trait)]
    #[php(name = "default")]
    pub fn default() -> RedactionConfig {
        hacienda::redaction::RedactionConfig::default().into()
    }
}

#[derive(Clone)]
#[php_class]
#[php(name = "Hacienda\\RedactionEngine")]
pub struct RedactionEngine {
    inner: Arc<hacienda::redaction::RedactionEngine>,
}

#[php_impl]
impl RedactionEngine {
    /// Rewrite every span in `entities` according to the configured mode.
    ///
    /// `entities` must be offset-ordered and non-overlapping — the output of
    /// `merge_entities` satisfies both. Spans that
    /// would go backwards or past the end of `text` are skipped rather than panicking,
    /// so a caller passing unsorted spans loses redactions but never crashes.
    ///
    /// # Errors
    ///
    /// Returns `RedactionError::Pseudonym` if a span cannot be tokenised — in practice
    /// only a custom category whose name contains a token delimiter. The whole call fails
    /// rather than emitting a partially-redacted document: the alternative is returning
    /// text that looks redacted and still contains the span.
    pub fn redact(&self, text: String, entities: &ext_php_rs::types::ZendHashTable) -> PhpResult<RedactionResult> {
        let mut entities_core_result: Vec<hacienda::MergedEntity> = Vec::new();
        for (_, item) in entities.iter() {
            if let Some(parsed) = <&MergedEntity as ext_php_rs::convert::FromZval>::from_zval(item) {
                entities_core_result.push(parsed.clone().into());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to MergedEntity".to_string(),
                ));
            }
        }
        let entities_core: Vec<hacienda::MergedEntity> = entities_core_result;
        let result = self.inner.redact(&text, &entities_core[..]).map_err(alef_php_err)?;
        Ok(result.into())
    }
}

