#[derive(Clone, serde::Serialize, serde::Deserialize, Default)]
#[php_class]
#[php(name = "Hacienda\\RedactionReport")]
#[serde(default)]
pub struct RedactionReport {
    /// Individual redaction findings in original-source byte order.
    pub findings: Vec<RedactionFinding>,
    /// Total number of redactions applied across the document.
    #[php(prop, name = "totalRedacted")]
    #[serde(alias = "totalRedacted")]
    pub total_redacted: u32,
}

#[php_impl]
impl RedactionReport {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(findings: &ext_php_rs::types::ZendHashTable, totalRedacted: u32) -> PhpResult<Self> {
        let mut findings_core_result: Vec<RedactionFinding> = Vec::new();
        for (_, item) in findings.iter() {
            if let Some(parsed) = <&RedactionFinding as ext_php_rs::convert::FromZval>::from_zval(item) {
                findings_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to RedactionFinding".to_string(),
                ));
            }
        }
        let findings_core: Vec<RedactionFinding> = findings_core_result;
        Ok(Self {
            findings: findings_core,
            total_redacted: totalRedacted,
        })
    }

    #[php(getter)]
    pub fn get_findings(&self) -> Vec<RedactionFinding> {
        self.findings.clone()
    }
    #[php(name = "getFindings")]
    pub fn read_findings(&self) -> Vec<RedactionFinding> {
        self.get_findings()
    }

    pub fn get_total_redacted(&self) -> u32 {
        self.total_redacted.clone()
    }
}

