#[php_class]
#[php(name = "Hacienda\\RevisionDelta")]
#[serde(default)]
pub struct RevisionDelta {
    /// Line-level content changes for this revision.
    pub content: Vec<DiffLine>,
    /// Cell-level table changes for this revision.
    #[serde(alias = "tableChanges")]
    pub table_changes: Vec<CellChange>,
    /// Formatting or metadata property changes for this revision.
    #[serde(alias = "propertyChanges")]
    #[serde(default)]
    pub property_changes: Vec<PropertyChange>,
}

impl Default for RevisionDelta {
    fn default() -> Self {
        <xberg::RevisionDelta as Default>::default().into()
    }
}

#[php_impl]
impl RevisionDelta {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        content: &ext_php_rs::types::ZendHashTable,
        tableChanges: &ext_php_rs::types::ZendHashTable,
        propertyChanges: &ext_php_rs::types::ZendHashTable,
    ) -> PhpResult<Self> {
        let mut content_core_result: Vec<DiffLine> = Vec::new();
        for (_, item) in content.iter() {
            if let Some(parsed) = <&DiffLine as ext_php_rs::convert::FromZval>::from_zval(item) {
                content_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to DiffLine".to_string(),
                ));
            }
        }
        let content_core: Vec<DiffLine> = content_core_result;
        let mut tableChanges_core_result: Vec<CellChange> = Vec::new();
        for (_, item) in tableChanges.iter() {
            if let Some(parsed) = <&CellChange as ext_php_rs::convert::FromZval>::from_zval(item) {
                tableChanges_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to CellChange".to_string(),
                ));
            }
        }
        let tableChanges_core: Vec<CellChange> = tableChanges_core_result;
        let mut propertyChanges_core_result: Vec<PropertyChange> = Vec::new();
        for (_, item) in propertyChanges.iter() {
            if let Some(parsed) = <&PropertyChange as ext_php_rs::convert::FromZval>::from_zval(item) {
                propertyChanges_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to PropertyChange".to_string(),
                ));
            }
        }
        let propertyChanges_core: Vec<PropertyChange> = propertyChanges_core_result;
        Ok(Self {
            content: content_core,
            table_changes: tableChanges_core,
            property_changes: propertyChanges_core,
        })
    }

    #[php(getter)]
    pub fn get_content(&self) -> Vec<DiffLine> {
        self.content.clone()
    }
    #[php(name = "getContent")]
    pub fn read_content(&self) -> Vec<DiffLine> {
        self.get_content()
    }

    #[php(getter)]
    pub fn get_table_changes(&self) -> Vec<CellChange> {
        self.table_changes.clone()
    }
    #[php(name = "getTableChanges")]
    pub fn read_table_changes(&self) -> Vec<CellChange> {
        self.get_table_changes()
    }

    #[php(getter)]
    pub fn get_property_changes(&self) -> Vec<PropertyChange> {
        self.property_changes.clone()
    }
    #[php(name = "getPropertyChanges")]
    pub fn read_property_changes(&self) -> Vec<PropertyChange> {
        self.get_property_changes()
    }
}

