#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "Hacienda\\XbergRedactionConfig")]
#[serde(default)]
pub struct XbergRedactionConfig {
    /// Categories to redact. Empty means "every category supported by the engine."
    #[serde(default)]
    pub categories: Vec<XbergPiiCategory>,
    /// Strategy applied to every match.
    #[php(prop, name = "strategy")]
    #[serde(default = "crate::serde_defaults::xberg_redaction_config_strategy")]
    #[serde(skip_serializing_if = "String::is_empty")]
    pub strategy: String,
    /// Optional NER backend — required to redact PERSON / ORGANIZATION / LOCATION
    /// categories (the pure-Rust pattern engine only covers regex-detectable PII).
    pub ner: Option<NerConfig>,
    /// When `true`, chunk byte ranges are kept consistent with the rewritten content by
    /// adjusting `byte_start` / `byte_end` after replacement. When `false`, chunk byte
    /// ranges still refer to the *original* content offsets — useful when downstream
    /// consumers want to map findings back to the original document.
    #[php(prop, name = "preserveOffsets")]
    #[serde(default = "crate::serde_defaults::xberg_redaction_config_preserve_offsets")]
    #[serde(alias = "preserveOffsets")]
    pub preserve_offsets: bool,
    /// Arbitrary user-supplied literal terms to redact.
    ///
    /// Each term is treated as a regex hit against the document, surfacing as
    /// `PiiCategory.Custom(label)` in `RedactionFinding`
    /// where `label` is the per-term label (defaulting to the literal value itself).
    /// Case-insensitive by default; set `RedactionTerm.case_sensitive` for exact match.
    ///
    /// Use this when you need to redact tenant-specific tokens (employee IDs,
    /// project codes, internal product names) without writing a custom plugin.
    #[serde(alias = "customTerms")]
    #[serde(default)]
    pub custom_terms: Vec<RedactionTerm>,
    /// Arbitrary user-supplied regex patterns to redact.
    ///
    /// Same surfacing semantics as `custom_terms`: each
    /// hit becomes a `PiiCategory.Custom(label)` finding. Patterns are validated
    /// at config-construction time via `RedactionConfig.validate`.
    #[serde(alias = "customPatterns")]
    #[serde(default)]
    pub custom_patterns: Vec<RedactionPattern>,
    /// Findings supplied inline by an external inspection engine.
    #[serde(default)]
    pub findings: Vec<ExternalRedactionFinding>,
    /// Minimum accepted confidence for scored external findings. Findings without a score remain eligible.
    #[php(prop, name = "minScore")]
    #[serde(alias = "minScore")]
    #[serde(default)]
    pub min_score: Option<f32>,
    /// JSON array or JSON Lines file containing external findings.
    #[php(prop, name = "findingsPath")]
    #[serde(alias = "findingsPath")]
    #[serde(default)]
    pub findings_path: Option<String>,
    /// Unit used by configured findings that derive their text from offsets.
    #[php(prop, name = "findingsOffsetEncoding")]
    #[serde(default = "crate::serde_defaults::xberg_redaction_config_findings_offset_encoding")]
    #[serde(skip_serializing_if = "String::is_empty")]
    #[serde(alias = "findingsOffsetEncoding")]
    pub findings_offset_encoding: String,
}

impl Default for XbergRedactionConfig {
    fn default() -> Self {
        <xberg::RedactionConfig as Default>::default().into()
    }
}

#[php_impl]
impl XbergRedactionConfig {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::from_message(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        categories: &ext_php_rs::types::ZendHashTable,
        strategy: String,
        preserveOffsets: bool,
        customTerms: &ext_php_rs::types::ZendHashTable,
        customPatterns: &ext_php_rs::types::ZendHashTable,
        findings: &ext_php_rs::types::ZendHashTable,
        findingsOffsetEncoding: Option<String>,
        ner: Option<&NerConfig>,
        minScore: Option<f32>,
        findingsPath: Option<String>,
    ) -> PhpResult<Self> {
        let mut categories_core_result: Vec<XbergPiiCategory> = Vec::new();
        for (_, item) in categories.iter() {
            if let Some(parsed) = <&XbergPiiCategory as ext_php_rs::convert::FromZval>::from_zval(item) {
                categories_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to XbergPiiCategory".to_string(),
                ));
            }
        }
        let categories_core: Vec<XbergPiiCategory> = categories_core_result;
        let mut customTerms_core_result: Vec<RedactionTerm> = Vec::new();
        for (_, item) in customTerms.iter() {
            if let Some(parsed) = <&RedactionTerm as ext_php_rs::convert::FromZval>::from_zval(item) {
                customTerms_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to RedactionTerm".to_string(),
                ));
            }
        }
        let customTerms_core: Vec<RedactionTerm> = customTerms_core_result;
        let mut customPatterns_core_result: Vec<RedactionPattern> = Vec::new();
        for (_, item) in customPatterns.iter() {
            if let Some(parsed) = <&RedactionPattern as ext_php_rs::convert::FromZval>::from_zval(item) {
                customPatterns_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to RedactionPattern".to_string(),
                ));
            }
        }
        let customPatterns_core: Vec<RedactionPattern> = customPatterns_core_result;
        let mut findings_core_result: Vec<ExternalRedactionFinding> = Vec::new();
        for (_, item) in findings.iter() {
            if let Some(parsed) = <&ExternalRedactionFinding as ext_php_rs::convert::FromZval>::from_zval(item) {
                findings_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to ExternalRedactionFinding".to_string(),
                ));
            }
        }
        let findings_core: Vec<ExternalRedactionFinding> = findings_core_result;
        Ok(Self {
            categories: categories_core,
            strategy,
            ner: ner.cloned(),
            preserve_offsets: preserveOffsets,
            custom_terms: customTerms_core,
            custom_patterns: customPatterns_core,
            findings: findings_core,
            min_score: minScore,
            findings_path: findingsPath,
            findings_offset_encoding: findingsOffsetEncoding
                .unwrap_or_else(crate::serde_defaults::xberg_redaction_config_findings_offset_encoding),
        })
    }

    #[php(getter)]
    pub fn get_categories(&self) -> Vec<XbergPiiCategory> {
        self.categories.clone()
    }
    #[php(name = "getCategories")]
    pub fn read_categories(&self) -> Vec<XbergPiiCategory> {
        self.get_categories()
    }

    pub fn get_strategy(&self) -> String {
        self.strategy.clone()
    }

    #[php(getter)]
    pub fn get_ner(&self) -> Option<NerConfig> {
        self.ner.clone().map(Into::into)
    }
    #[php(name = "getNer")]
    pub fn read_ner(&self) -> Option<NerConfig> {
        self.get_ner()
    }

    pub fn set_ner(&mut self, value: Option<&NerConfig>) {
        self.ner = value.map(|value| value.clone().into());
    }

    pub fn get_preserve_offsets(&self) -> bool {
        self.preserve_offsets.clone()
    }

    #[php(getter)]
    pub fn get_custom_terms(&self) -> Vec<RedactionTerm> {
        self.custom_terms.clone()
    }
    #[php(name = "getCustomTerms")]
    pub fn read_custom_terms(&self) -> Vec<RedactionTerm> {
        self.get_custom_terms()
    }

    #[php(getter)]
    pub fn get_custom_patterns(&self) -> Vec<RedactionPattern> {
        self.custom_patterns.clone()
    }
    #[php(name = "getCustomPatterns")]
    pub fn read_custom_patterns(&self) -> Vec<RedactionPattern> {
        self.get_custom_patterns()
    }

    #[php(getter)]
    pub fn get_findings(&self) -> Vec<ExternalRedactionFinding> {
        self.findings.clone()
    }
    #[php(name = "getFindings")]
    pub fn read_findings(&self) -> Vec<ExternalRedactionFinding> {
        self.get_findings()
    }

    pub fn get_min_score(&self) -> Option<f32> {
        self.min_score.clone()
    }

    pub fn get_findings_path(&self) -> Option<String> {
        self.findings_path.clone()
    }

    pub fn get_findings_offset_encoding(&self) -> String {
        self.findings_offset_encoding.clone()
    }
}

