// `EntityCategory` is EXTERNALLY tagged in the core crate, so serde writes a unit variant as a
// bare string and a data variant as a single-keyed object whose value IS the payload -- never the
// flat `{"type": ...}` object this class stores its state in. A derived impl therefore
// could not read the wire the core type emits, and every value of this type failed to
// deserialize. The flat object form is still accepted so JSON this class previously produced
// keeps round-tripping.
impl serde::Serialize for EntityCategory {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        match self.type_tag.as_str() {
            "person" => serializer.serialize_str("person"),
            "organization" => serializer.serialize_str("organization"),
            "location" => serializer.serialize_str("location"),
            "date" => serializer.serialize_str("date"),
            "time" => serializer.serialize_str("time"),
            "money" => serializer.serialize_str("money"),
            "percent" => serializer.serialize_str("percent"),
            "email" => serializer.serialize_str("email"),
            "phone" => serializer.serialize_str("phone"),
            "url" => serializer.serialize_str("url"),
            "custom" => {
                use serde::ser::SerializeMap;
                let mut map = serializer.serialize_map(Some(1))?;
                map.serialize_entry("custom", self.custom.as_deref().unwrap_or_default())?;
                map.end()
            }
            other => serializer.serialize_str(other),
        }
    }
}

