impl FormatMetadata {
    /// The payload of a variant: the object nested under `key` when it is the only entry, else the
    /// whole object (serde writes the payload fields next to the tag).
    fn payload<T: serde::de::DeserializeOwned>(
        mut object: serde_json::Map<String, serde_json::Value>,
        key: &str,
    ) -> Result<T, serde_json::Error> {
        let nested = object.len() == 1 && object.get(key).is_some_and(serde_json::Value::is_object);
        let source = if nested {
            object.remove(key).unwrap_or_default()
        } else {
            serde_json::Value::Object(object)
        };
        serde_json::from_value(source)
    }
}

