#[php_class]
#[php(name = "Hacienda\\RedactionAction")]
#[derive(Clone, Default)]
pub struct RedactionAction {
    type_tag: String,
    pub custom: Option<String>,
}

// `RedactionAction` is EXTERNALLY tagged in the core crate, so serde writes a unit variant as a
// bare string and a data variant as a single-keyed object whose value IS the payload -- never the
// flat `{"type": ...}` object this class stores its state in. A derived impl therefore
// could not read the wire the core type emits, and every value of this type failed to
// deserialize. The flat object form is still accepted so JSON this class previously produced
// keeps round-tripping.
impl serde::Serialize for RedactionAction {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        match self.type_tag.as_str() {
            "mask" => serializer.serialize_str("mask"),
            "hash" => serializer.serialize_str("hash"),
            "pseudonymize" => serializer.serialize_str("pseudonymize"),
            "remove" => serializer.serialize_str("remove"),
            "reveal" => serializer.serialize_str("reveal"),
            "custom" => {
                use serde::ser::SerializeMap;
                let mut map = serializer.serialize_map(Some(1))?;
                map.serialize_entry("custom", self.custom.as_deref().unwrap_or_default())?;
                map.end()
            }
            other => serializer.serialize_str(other),
        }
    }
}

impl<'de> serde::Deserialize<'de> for RedactionAction {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        struct AlefExternalVisitor;
        impl<'de> serde::de::Visitor<'de> for AlefExternalVisitor {
            type Value = RedactionAction;

            fn expecting(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                formatter.write_str("a string or an object for RedactionAction")
            }

            fn visit_str<E>(self, value: &str) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                match value {
                    "mask" => Ok(RedactionAction {
                        type_tag: "mask".to_string(),
                        custom: None,
                    }),
                    "hash" => Ok(RedactionAction {
                        type_tag: "hash".to_string(),
                        custom: None,
                    }),
                    "pseudonymize" => Ok(RedactionAction {
                        type_tag: "pseudonymize".to_string(),
                        custom: None,
                    }),
                    "remove" => Ok(RedactionAction {
                        type_tag: "remove".to_string(),
                        custom: None,
                    }),
                    "reveal" => Ok(RedactionAction {
                        type_tag: "reveal".to_string(),
                        custom: None,
                    }),
                    "" => Ok(RedactionAction::default()),
                    value => Err(serde::de::Error::unknown_variant(
                        value,
                        &["mask", "hash", "pseudonymize", "remove", "reveal", "custom"],
                    )),
                }
            }

            fn visit_map<A>(self, mut map: A) -> Result<Self::Value, A::Error>
            where
                A: serde::de::MapAccess<'de>,
            {
                let mut entries: Vec<(String, serde_json::Value)> = Vec::new();
                while let Some(entry) = map.next_entry::<String, serde_json::Value>()? {
                    entries.push(entry);
                }
                if entries.iter().any(|(key, _)| key == "type") {
                    let mut value = RedactionAction::default();
                    for (key, entry) in entries {
                        match key.as_str() {
                            "type" => value.type_tag = entry.as_str().unwrap_or_default().to_string(),
                            "custom" => value.custom = entry.as_str().map(str::to_string),
                            _ => {}
                        }
                    }
                    return Ok(value);
                }
                match entries.into_iter().next() {
                    Some((key, entry)) if key == "custom" => Ok(RedactionAction {
                        type_tag: "custom".to_string(),
                        custom: entry.as_str().map(str::to_string),
                    }),
                    Some((key, _)) => Err(serde::de::Error::unknown_variant(
                        key.as_str(),
                        &["mask", "hash", "pseudonymize", "remove", "reveal", "custom"],
                    )),
                    None => Ok(RedactionAction::default()),
                }
            }
        }
        deserializer.deserialize_any(AlefExternalVisitor)
    }
}

