#[php_class]
#[php(name = "Hacienda\\HaciendaApi")]
pub struct HaciendaApi;

#[php_impl]
impl HaciendaApi {
    /// Alias with a descriptive name for callers that prefer the output type as the verb.
    #[php(name = "buildEditorProjection")]
    pub fn build_editor_projection(
        document: Option<&ExtractedDocument>,
        options: &EditorProjectionOptions,
    ) -> EditorEnvelope {
        let document_core: Option<xberg::ExtractedDocument> = document.map(|v| v.clone().into());
        let options_core: hacienda::editor_projection::EditorProjectionOptions = options.clone().into();
        hacienda::editor_projection::build_editor_projection(&document_core.unwrap_or_default(), &options_core).into()
    }

    /// The deterministic pattern set the `RegexEngine` compiles.
    ///
    /// Order matters: earlier patterns win when two matches overlap, because
    /// `RegexEngine::find_all` sorts by start offset and drops later overlapping spans.
    #[php(name = "builtinPatterns")]
    pub fn builtin_patterns() -> Vec<PatternMeta> {
        hacienda::pii::builtin_patterns().into_iter().map(Into::into).collect()
    }

    #[php(name = "cacheStats")]
    pub fn cache_stats() -> PhpResult<CacheStats> {
        let result = hacienda::xberg_surface::cache_stats().map_err(alef_php_err)?;
        Ok(result.into())
    }

    /// Probe the ONNX runtime once per process so capability requests do not repeatedly load FFI.
    #[php(name = "cachedOnnxRuntimeStatus")]
    pub fn cached_onnx_runtime_status() -> CapabilityStatus {
        hacienda::capabilities::cached_onnx_runtime_status().into()
    }

    #[php(name = "clearCache")]
    pub fn clear_cache() -> PhpResult<CacheClearResult> {
        let result = hacienda::xberg_surface::clear_cache().map_err(alef_php_err)?;
        Ok(result.into())
    }

    /// Compute the chain hash linking an entry to its predecessor.
    ///
    /// The timestamp is deliberately excluded so verification is reproducible.
    #[php(name = "computeChainHash")]
    pub fn compute_chain_hash(prevChainHash: String, seq: i64, fields: &ChainHashFields) -> String {
        let fields_core: hacienda::audit::ChainHashFields = fields.clone().into();
        hacienda::audit::compute_chain_hash(&prevChainHash, seq as u64, fields_core)
    }

    /// Compute the blake3 hash that seals a segment's metadata.
    ///
    /// Every field is length-prefixed before being fed to the hasher. This prevents
    /// ambiguous splits: without length prefixes, `("ab", "c")` and `("a", "bc")` would
    /// produce the same byte sequence. `compute_chain_hash` in `entry.rs` uses fixed-width
    /// integers (which are self-delimiting) alongside string bytes and does not need this
    /// guard, but the seal fields are all variable-length strings, so it is required here.
    ///
    /// The field order and encoding here is the canonical definition of the seal hash for
    /// this crate. Changing either breaks all stored seals.
    ///
    /// The nine arguments map one-to-one to the nine `SegmentSeal` fields that the hash
    /// covers. Wrapping them in a struct would force callers to construct one just to call this
    /// function; keeping them flat is both more legible and consistent with `compute_chain_hash`.
    #[php(name = "computeSealHash")]
    pub fn compute_seal_hash(
        prevSealHash: Option<String>,
        segmentId: String,
        tenantId: String,
        nodeId: String,
        configHash: String,
        sealedTip: String,
        entryCount: i64,
        openedAt: String,
        sealedAt: String,
    ) -> String {
        hacienda::audit::compute_seal_hash(
            prevSealHash.as_deref(),
            &segmentId,
            &tenantId,
            &nodeId,
            &configHash,
            &sealedTip,
            entryCount as u64,
            &openedAt,
            &sealedAt,
        )
    }

    #[php(name = "detectMimeType")]
    pub fn detect_mime_type(bytes: PhpBytes, filename: Option<String>) -> PhpResult<String> {
        let result =
            hacienda::xberg_surface::detect_mime_type(&bytes.0[..], filename.as_deref()).map_err(alef_php_err)?;
        Ok(result)
    }

    /// Boost each entity's confidence toward `1.0` when one of its category's context words
    /// (`entity.context_words`, set by `find_all` from the
    /// originating `PatternMeta`) appears within `PREFIX_WORDS` tokens
    /// before or `SUFFIX_WORDS` tokens after its span in `text`.
    ///
    /// A no-op for an entity that's already at `1.0` (nothing to boost) or that has no
    /// context words calibrated for its category.
    #[php(name = "enhance")]
    pub fn enhance(entities: &ext_php_rs::types::ZendHashTable, text: String) -> PhpResult<()> {
        let mut entities_core_result: Vec<hacienda::RegexEntity> = Vec::new();
        for (_, item) in entities.iter() {
            if let Some(parsed) = <&RegexEntity as ext_php_rs::convert::FromZval>::from_zval(item) {
                entities_core_result.push(parsed.clone().into());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to RegexEntity".to_string(),
                ));
            }
        }
        let entities_core: Vec<hacienda::RegexEntity> = entities_core_result;
        Ok(hacienda::pii::context::enhance(&entities_core[..], &text))
    }

    /// RFC 4180 CSV with a header row.
    #[php(name = "exportCsv")]
    pub fn export_csv(chain: &AuditChain) -> PhpResult<String> {
        let result = hacienda::audit::export_csv(&chain.inner).map_err(alef_php_err)?;
        Ok(String::from_utf8_lossy(&result[..]).into_owned())
    }

    /// A single pretty-printed JSON array.
    #[php(name = "exportJson")]
    pub fn export_json(chain: &AuditChain) -> PhpResult<String> {
        let result = hacienda::audit::export_json(&chain.inner).map_err(alef_php_err)?;
        Ok(String::from_utf8_lossy(&result[..]).into_owned())
    }

    /// One JSON object per line, in chain order.
    #[php(name = "exportJsonLines")]
    pub fn export_json_lines(chain: &AuditChain) -> PhpResult<String> {
        let result = hacienda::audit::export_json_lines(&chain.inner).map_err(alef_php_err)?;
        Ok(String::from_utf8_lossy(&result[..]).into_owned())
    }

    /// Build the checklist for the controls this pipeline actually implements.
    ///
    /// Status reflects what the code does, not an aspiration: articles covered by a
    /// concrete module are `Implemented`, articles that need organisational process on
    /// top of a generated artefact are `Partial`.
    #[php(name = "generateChecklist")]
    pub fn generate_checklist() -> ComplianceChecklist {
        hacienda::compliance::generate_checklist().into()
    }

    /// Generate a new API key and its hash.
    ///
    /// The raw key uses `hcd_live_` prefix followed by 43 base62 characters
    /// (256 bits of entropy). The hash uses Argon2id with a unique salt per key.
    ///
    /// # Errors
    /// Returns `ApiKeyError::Generation` if random generation fails,
    /// or `ApiKeyError::Hashing` if Argon2id hashing fails.
    #[php(name = "generateKey")]
    pub fn generate_key() -> PhpResult<ApiKeyPair> {
        let result = hacienda::auth::keys::generate_key().map_err(alef_php_err)?;
        Ok(result.into())
    }

    #[php(name = "generateModelCard")]
    pub fn generate_model_card(modelName: String) -> ModelCard {
        hacienda::compliance::generate_model_card(&modelName).into()
    }

    #[php(name = "generateReport")]
    pub fn generate_report(incident: &PiiIncident) -> DoraReport {
        let incident_core: hacienda::compliance::PiiIncident = incident.clone().into();
        hacienda::compliance::generate_report(&incident_core).into()
    }

    /// Whether a token category label (e.g. `"SSN"`) is high-sensitivity.
    #[php(name = "isHighSensitivityCategory")]
    pub fn is_high_sensitivity_category(label: String) -> bool {
        hacienda::reveal_ticket::is_high_sensitivity_category(&label)
    }

    /// Whether a request's scope touches at least one high-sensitivity category — the trigger
    /// for the double-approval rule (dossier #120): either a listed token's category header,
    /// or a `field_scope` category label.
    #[php(name = "isHighSensitivityScope")]
    pub fn is_high_sensitivity_scope(tokenIds: Vec<String>, fieldScope: Vec<String>) -> bool {
        hacienda::reveal_ticket::is_high_sensitivity_scope(&tokenIds[..], &fieldScope[..])
    }

    /// Compute the deterministic lookup digest for a raw API key.
    ///
    /// This is a plain BLAKE3 hash, hex-encoded — the same construction
    /// `InMemoryTokenStore::secret_key` in `auth::authn` uses for static tokens. It is
    /// deliberately *not* a slow password hash: unlike `key_hash`, which exists to defend a
    /// leaked database, `lookup_hash` exists only so a presented key can be looked up by
    /// value. Verification of possession still goes through `verify_key` against
    /// `key_hash`; `lookup_hash` never gates access on its own.
    #[php(name = "lookupKey")]
    pub fn lookup_key(rawKey: String) -> String {
        hacienda::auth::keys::lookup_key(&rawKey)
    }

    /// Luhn (mod-10) check over the digit characters of `s`.
    #[php(name = "luhnValid")]
    pub fn luhn_valid(s: String) -> bool {
        hacienda::pii::validators::luhn_valid(&s)
    }

    /// Reconcile regex and model detections into a single non-overlapping, offset-ordered list.
    ///
    /// Two spans are treated as the same detection when their overlap ratio exceeds
    /// `config.overlap_threshold`; the winner is chosen by `config.priority`.
    #[php(name = "mergeEntities")]
    pub fn merge_entities(
        regexEntities: &ext_php_rs::types::ZendHashTable,
        modelEntities: &ext_php_rs::types::ZendHashTable,
        config: Option<&MergeConfig>,
    ) -> PhpResult<Vec<MergedEntity>> {
        let mut regexEntities_core_result: Vec<hacienda::RegexEntity> = Vec::new();
        for (_, item) in regexEntities.iter() {
            if let Some(parsed) = <&RegexEntity as ext_php_rs::convert::FromZval>::from_zval(item) {
                regexEntities_core_result.push(parsed.clone().into());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to RegexEntity".to_string(),
                ));
            }
        }
        let regexEntities_core: Vec<hacienda::RegexEntity> = regexEntities_core_result;
        let mut modelEntities_core_result: Vec<hacienda::ModelEntity> = Vec::new();
        for (_, item) in modelEntities.iter() {
            if let Some(parsed) = <&ModelEntity as ext_php_rs::convert::FromZval>::from_zval(item) {
                modelEntities_core_result.push(parsed.clone().into());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to ModelEntity".to_string(),
                ));
            }
        }
        let modelEntities_core: Vec<hacienda::ModelEntity> = modelEntities_core_result;
        let config_core: Option<hacienda::pii::MergeConfig> = config.map(|v| v.clone().into());
        Ok(
            hacienda::pii::merge_entities(regexEntities_core, modelEntities_core, &config_core.unwrap_or_default())
                .into_iter()
                .map(Into::into)
                .collect(),
        )
    }

    /// Probe the ONNX runtime prerequisite without exposing paths or loading document data.
    #[php(name = "onnxRuntimeStatus")]
    pub fn onnx_runtime_status() -> CapabilityStatus {
        hacienda::capabilities::onnx_runtime_status().into()
    }

    /// Convert an already Hacienda-redacted Xberg document into an editor envelope.
    ///
    /// The body is copied as redacted text and token occurrences are marked in ProseMirror
    /// JSON. Metadata is stricter: only Hacienda token occurrences are retained, so an
    /// unredacted title, filename, author, subject, keyword, or attachment name cannot leak
    /// through this boundary.
    #[php(name = "projectDocument")]
    pub fn project_document(document: Option<&ExtractedDocument>, options: &EditorProjectionOptions) -> EditorEnvelope {
        let document_core: Option<xberg::ExtractedDocument> = document.map(|v| v.clone().into());
        let options_core: hacienda::editor_projection::EditorProjectionOptions = options.clone().into();
        hacienda::editor_projection::project_document(&document_core.unwrap_or_default(), &options_core).into()
    }

    /// Convenience form for callers that only have opaque document/version references.
    #[php(name = "projectDocumentWithRefs")]
    pub fn project_document_with_refs(
        document: Option<&ExtractedDocument>,
        documentRef: String,
        versionRef: String,
    ) -> EditorEnvelope {
        let document_core: Option<xberg::ExtractedDocument> = document.map(|v| v.clone().into());
        hacienda::editor_projection::project_document_with_refs(
            &document_core.unwrap_or_default(),
            documentRef,
            versionRef,
        )
        .into()
    }

    /// Compose the common capability report from surface-specific runtime checks.
    ///
    /// `ner` must come from the detector the reporting surface actually uses. Passing
    /// `NerRuntimeState::unavailable()` is honest for a surface that never built a
    /// facade; reading a process-global model id here would let one surface's model
    /// leak into another surface's report.
    #[php(name = "report")]
    pub fn report(
        version: String,
        embeddingCompiled: bool,
        onnxRuntime: &CapabilityStatus,
        serviceReady: bool,
        ner: &NerRuntimeState,
    ) -> CapabilityReport {
        let onnxRuntime_core: hacienda::capabilities::CapabilityStatus = onnxRuntime.clone().into();
        let ner_core: hacienda::pii::NerRuntimeState = ner.clone().into();
        hacienda::capabilities::report(&version, embeddingCompiled, onnxRuntime_core, serviceReady, ner_core).into()
    }

    /// Map an xberg entity category onto the PII taxonomy.
    ///
    /// Categories with no PII counterpart (Money, Percent, Date, Time) are carried through
    /// as `Custom` rather than dropped, so a caller redacting everything still sees them.
    #[php(name = "toPiiCategory")]
    pub fn to_pii_category(category: &EntityCategory) -> PiiCategory {
        let category_core: xberg::EntityCategory = category.clone().into();
        hacienda::pii::ner::to_pii_category(&category_core).into()
    }

    /// Credit card: strip separators, require 12-19 digits, then Luhn.
    #[php(name = "validateCreditCard")]
    pub fn validate_credit_card(text: String) -> Option<bool> {
        hacienda::pii::validators::validate_credit_card(&text)
    }

    /// Bitcoin/Litecoin legacy address: Base58Check decode and verify the 4-byte
    /// double-SHA256 checksum. Both chains share the same Base58Check construction, so this
    /// validates `1`/`3` (BTC P2PKH/P2SH) and `L`/`M` (LTC) addresses -- the shapes
    /// `builtin_patterns`'s `CryptoWallet` pattern matches.
    #[php(name = "validateCryptoWallet")]
    pub fn validate_crypto_wallet(text: String) -> Option<bool> {
        hacienda::pii::validators::validate_crypto_wallet(&text)
    }

    /// IBAN: ISO 13616 mod-97 check (remainder must be 1).
    #[php(name = "validateIban")]
    pub fn validate_iban(text: String) -> Option<bool> {
        hacienda::pii::validators::validate_iban(&text)
    }

    /// US SSN: reject structurally-impossible numbers (area 000/666/9xx, group 00, serial
    /// 0000). Returns `None` for plausible numbers so the pattern's medium confidence score
    /// is preserved rather than promoted to 1.0 -- unlike the other validators here, an SSN
    /// has no checksum that can positively confirm it, only ways to rule one out.
    #[php(name = "validateUsSsn")]
    pub fn validate_us_ssn(text: String) -> Option<bool> {
        hacienda::pii::validators::validate_us_ssn(&text)
    }

    /// VIN: 17 chars, ISO 3779 mod-11 check digit at position 9 (`X` == 10).
    /// North-American VINs (WMI 1-5) with a bad check digit are rejected (`Some(false)`);
    /// elsewhere a bad check digit yields `None` (many real non-NA VINs omit a valid check
    /// digit), preserving the base score.
    #[php(name = "validateVin")]
    pub fn validate_vin(text: String) -> Option<bool> {
        hacienda::pii::validators::validate_vin(&text)
    }

    /// Recompute every chain hash in `entries` from genesis and report the first mismatch.
    ///
    /// The slice-only counterpart of `AuditChain::verify`, for callers holding a
    /// deserialized `Vec<AuditEntry>` (e.g. `hacienda-cli`'s `audit verify`, reading back a
    /// flat JSON export) without also holding an `AuditChain`. Each entry's own `config_hash`
    /// is already part of `AuditEntry::chain_hash_fields`,
    /// so no chain-level config hash is needed here — this is exactly the loop
    /// `AuditChain::verify` runs internally.
    ///
    /// # Errors
    ///
    /// Returns `AuditError::ChainIntegrity` naming the index of the first entry whose
    /// recorded hash does not match its recomputed value.
    #[php(name = "verifyEntries")]
    pub fn verify_entries(entries: &ext_php_rs::types::ZendHashTable) -> PhpResult<()> {
        let mut entries_core_result: Vec<hacienda::AuditEntry> = Vec::new();
        for (_, item) in entries.iter() {
            if let Some(parsed) = <&AuditEntry as ext_php_rs::convert::FromZval>::from_zval(item) {
                entries_core_result.push(parsed.clone().into());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to AuditEntry".to_string(),
                ));
            }
        }
        let entries_core: Vec<hacienda::AuditEntry> = entries_core_result;
        let result = hacienda::audit::verify_entries(&entries_core[..]).map_err(alef_php_err)?;
        Ok(result)
    }

    /// Verify a candidate key against a stored Argon2id hash.
    ///
    /// Returns `true` if the key matches the hash, `false` otherwise.
    /// Uses constant-time verification to prevent timing attacks.
    #[php(name = "verifyKey")]
    pub fn verify_key(candidate: String, storedHash: String) -> PhpResult<bool> {
        let result = hacienda::auth::keys::verify_key(&candidate, &storedHash).map_err(alef_php_err)?;
        Ok(result)
    }

    /// Verify a slice of `SegmentSeal`s from a single node, oldest first.
    ///
    /// Two checks are applied to every seal:
    ///
    /// 1. **Self-integrity** — recompute `seal_hash` from the seal's own fields and compare.
    ///    Any field mutation (including blanking `prev_seal_hash`) is detected here.
    /// 2. **Link check** — confirm that `prev_seal_hash` matches the `seal_hash` of the
    ///    immediately preceding entry in the slice. An attacker who recomputes seal hashes
    ///    after splicing seals together would still break this check.
    ///
    /// The two together are what defeat truncation. Dropping the oldest segment and blanking
    /// the new first seal's `prev_seal_hash` alters a field the hash covers, so check 1 fires.
    /// Recomputing the hash to match the blanked field satisfies check 1, but that changes the
    /// seal's own hash, so check 2 fires on its successor. An attacker who repairs both has had
    /// to re-mint every seal in the run — which is exactly the work a hash chain is meant to
    /// force, and what an anchor over these seal hashes will eventually make impossible.
    ///
    /// # Errors
    ///
    /// - `AuditError::SegmentIntegrity` — a seal's `seal_hash` does not match its fields.
    /// - `AuditError::SegmentLink` — a seal's `prev_seal_hash` does not match its
    ///   predecessor's `seal_hash`.
    #[php(name = "verifySealChain")]
    pub fn verify_seal_chain(seals: &ext_php_rs::types::ZendHashTable) -> PhpResult<()> {
        let mut seals_core_result: Vec<hacienda::SegmentSeal> = Vec::new();
        for (_, item) in seals.iter() {
            if let Some(parsed) = <&SegmentSeal as ext_php_rs::convert::FromZval>::from_zval(item) {
                seals_core_result.push(parsed.clone().into());
            } else {
                return Err(ext_php_rs::exception::PhpException::from_message(
                    "Failed to convert array element to SegmentSeal".to_string(),
                ));
            }
        }
        let seals_core: Vec<hacienda::SegmentSeal> = seals_core_result;
        let result = hacienda::audit::verify_seal_chain(&seals_core[..]).map_err(alef_php_err)?;
        Ok(result)
    }

    #[php(name = "warmEmbeddingPreset")]
    pub fn warm_embedding_preset(name: String) -> PhpResult<WarmResult> {
        WORKER_RUNTIME.block_on(async {
            let result = hacienda::xberg_surface::warm_embedding_preset(&name)
                .await
                .map_err(alef_php_err)?;
            Ok(result.into())
        })
    }
}

